window.GUILIB_SEARCH = [{"t":"GuiLib","u":"index.html","k":"page","s":"A UI library for Minecraft Fabric mods that works like web development: React-style components and hooks in a Kotlin DSL with HTML tag names","b":"A UI library for Minecraft Fabric mods that works like web development: React-style components and hooks in a Kotlin DSL with HTML tag names, styled with real .css files. Kotlin Copy val Counter = component(\"Counter\") { var count by useState(0) div(className = \"card\") { span(className = \"label\") { +\"Clicked $count times\" } button(className = \"primary\", onClick = { count++ }) { +\"Click me\" } } } GuiLib.open(Counter, stylesheets = listOf(\"mymod:ui/counter.css\")) CSS Copy /* src/main/resources/assets/mymod/ui/counter.css */ body { display: flex; align-items: center; justify-content: center; } .card { display: flex; gap: 6px; align-items: center; padding: 8px 10px; background-color: #1e1f22; border-radius: 6px; } .primary { background-color: #5b8def; } .primary:hover { background-color: #6f9cf2; } Version 0.12.1 Minecraft 26.1.2, 26.2 & 26.3 Fabric Kotlin LGPL-3.0"},{"t":"Why GuiLib","u":"index.html#why-guilib","k":"GuiLib","s":"","b":"Developers and AI models already know HTML, React and CSS extremely well. GuiLib keeps their names and behaviour wherever possible ( padding , justify-content , :hover , useState , onClick , className , keys, event bubbling, …), so UIs can be written quickly and correctly. Where GuiLib differs from the web it is documented on Differences from the web . The built-in controls, rendered in-game (GUI scale 2). Click any screenshot to enlarge it."},{"t":"Features","u":"index.html#features","k":"GuiLib","s":"","b":"Components & hooks Function components with props, useState , useEffect , useMemo , useRef , context, keyed lists. Only changed components re-render. Real CSS Stylesheets from resources, cascade, specificity, !important , variables, calc() , :hover , :nth-child() . Errors are warnings, never crashes. Layout Box model, block & inline flow, flexbox , CSS grid , relative/absolute/fixed positioning, scroll containers. Animation transition and @keyframes for colors, sizes, opacity, gradients and transforms (translate, scale, rotate, skew). Rendering Anti-aliased rounded corners and borders, gradients, TTF text (Inter), the vanilla font, PNG & SVG images, items and player models. 25+ ready-made controls Inputs, switch, sliders, number field, selects with search, tabs, accordions, context menus, toasts, color picker, sortable lists …"},{"t":"Where to start","u":"index.html#where-to-start","k":"GuiLib","s":"","b":"Getting started : add GuiLib to your mod and open your first screen. Components & hooks : how UIs are structured. Elements and Form controls : everything you can put on screen. CSS : every supported selector, value and property. Differences from the web : read this once; it saves time. Use the search at the top (press / ) to jump to any function, hook or CSS class."},{"t":"Gallery","u":"index.html#gallery","k":"GuiLib","s":"","b":"Forms: inputs, select, checkbox, switches, sliders Tabs, accordion, context menu Color picker Transitions, keyframes, transforms CSS grid Drag-to-reorder lists Text, fonts and § codes Player models"},{"t":"Getting started","u":"getting-started.html","k":"page","s":"Add GuiLib to a Fabric mod, write a component and a stylesheet, and open it as a screen.","b":"Add GuiLib to a Fabric mod, write a component and a stylesheet, and open it as a screen."},{"t":"Installation","u":"getting-started.html#installation","k":"Getting started","s":"","b":"GuiLib is a Fabric mod published as net.sbo:guilib-<mc>-fabric to the SkyblockOverhaul Maven repository. Pick the artifact for your Minecraft version ( 26.1.2-fabric , 26.2-fabric or 26.3-fabric ) and bundle it jar-in-jar: build.gradle.kts Copy repositories { exclusiveContent { forRepository { maven(\"https://skyblockoverhaul.github.io/maven\") } filter { includeGroup(\"net.sbo\") } } } dependencies { // jar-in-jar: players don't need to install GuiLib separately implementation(include(\"net.sbo:guilib-26.2-fabric:0.12.1\")!!) } Declare the dependency in your fabric.mod.json : fabric.mod.json Copy \"depends\": { \"guilib\": \">=0.12.1\" } GuiLib needs fabric-api and fabric-language-kotlin . Your mod can be written in Kotlin or Java, but the DSL is designed for Kotlin."},{"t":"Your first screen","u":"getting-started.html#your-first-screen","k":"Getting started","s":"","b":"A UI is a component : a function that builds elements with the DSL. Elements are styled with a CSS file from your mod's resources. PartyScreen.kt Copy import net.sbo.guilib.core.dom.component import net.sbo.guilib.core.dsl.* // div, span, button, input, useState, … import net.sbo.guilib.fabric.GuiLib data class Party(val id: String, val leader: String, val size: Int) val PartyRow = component<Party>(\"PartyRow\") { party -> var expanded by useState(false) div(className = classNames(\"row\", \"expanded\" to expanded), onClick = { expanded = !expanded }) { span(className = \"leader\") { +party.leader } span(className = \"size\") { +\"${party.size}/5\" } if (expanded) button(className = \"join\", onClick = { e -> e.stopPropagation(); join(party.id) }) { +\"Join\" } } } val App = component(\"App\") { val (parties, setParties) = useState(emptyList<Party>()) useEffect { loadParties { result -> setParties(result) } } // once after mount; setters are thread-safe div(className = \"panel\") { h2 { +\"Parties\" } scroll(className = \"list\") { for (p in parties) PartyRow(p, key = p.id) // keys for lists, like React } } } // e.g. from a command or key binding: GuiLib.open(App, stylesheets = listOf(\"mymod:ui/parties.css\")) parties.css Copy /* src/main/resources/assets/mymod/ui/parties.css */ :root { --accent: #5b8def; } body { display: flex; align-items: center; justify-content: center; } /* body = the whole screen */ .panel { width: 300px; max-height: 80vh; padding: 8px; background-color: #1e1f22; border-radius: 6px; display: flex; flex-direction: column; } .list { flex-grow: 1; min-height: 0; } .row { display: flex; justify-content: space-between; padding: 3px 6px; border-radius: 3px; cursor: pointer; } .row:hover { background-color: #2b2d31; } .join { background-color: var(--accent); } px are GUI pixels and the default font size is 8px . Typical UI text is 7–10px, so web values like font-size: 14px look huge. See Differences from the web ."},{"t":"Opening screens","u":"getting-started.html#opening-screens","k":"Getting started","s":"","b":""},{"t":"GuiLib.open","u":"getting-started.html#guilib-open","k":"function","s":"Opens a component as a Minecraft screen and returns it. Must be called on the client thread (use GuiLib.runOnUi otherwise).","c":"","b":"# GuiLib.open function Opens a component as a Minecraft screen and returns it. Must be called on the client thread (use GuiLib.runOnUi otherwise). Copy fun GuiLib.open( app: ComponentType<Unit>, stylesheets: List<String> = emptyList(), title: String = app.name, vanillaBackground: Boolean = true, pauseGame: Boolean = false, scale: Float? = null, blurBackground: Boolean = true, metrics: Boolean = false, ): GuiLibScreen fun open(stylesheets: List<String> = emptyList(), title: String = \"GuiLib\", content: NodeBuilder.() -> Unit): GuiLibScreen Parameter Type Default Description app ComponentType<Unit> required The root component (without props). stylesheets List<String> emptyList() Resource locations of CSS files, e.g. \"mymod:ui/app.css\" → assets/mymod/ui/app.css . title String app.name Screen title (narration). vanillaBackground Boolean true Draw Minecraft's blurred/dimmed background behind the UI ( false = neither blur nor dark overlay). pauseGame Boolean false Pause singleplayer while open. scale Float? null The screen's own GUI scale (physical pixels per CSS px, fractions like 2.5f work), independent of Minecraft's; null = Minecraft's. Change it later with useScreenScale . blurBackground Boolean true false = no blur behind the screen, the dark overlay stays. Change it later with useBackgroundBlur . Also on GuiLib.screen(…) . metrics Boolean false Show the metrics overlay from the start (Ctrl + F12 toggles it anyway). Also on GuiLib.screen(…) . Example Copy GuiLib.open(App, stylesheets = listOf(\"mymod:ui/app.css\")) // Inline UI without declaring a component: GuiLib.open(listOf(\"mymod:ui/hello.css\")) { div(className = \"hello\") { +\"Hi!\" } }"},{"t":"GuiLib.screen","u":"getting-started.html#guilib-screen","k":"function","s":"Creates the screen without opening it, e.g. to return it from a config button or ModMenu integration.","c":"","b":"# GuiLib.screen function Creates the screen without opening it, e.g. to return it from a config button or ModMenu integration. Copy fun GuiLib.screen( app: ComponentType<Unit>, stylesheets: List<String> = emptyList(), title: String = app.name, ): GuiLibScreen Parameter Type Default Description app ComponentType<Unit> required Root component. stylesheets List<String> emptyList() CSS resource locations. title String app.name Screen title."},{"t":"GuiLib.close","u":"getting-started.html#guilib-close","k":"function","s":"Closes the current screen (e.g. from a close button: button(onClick = { GuiLib.close() }) ).","c":"","b":"# GuiLib.close function Closes the current screen (e.g. from a close button: button(onClick = { GuiLib.close() }) ). Copy fun close()"},{"t":"GuiLib.currentScreen","u":"getting-started.html#guilib-currentscreen","k":"function","s":"The screen that is currently open, on every supported Minecraft version.","c":"","b":"# GuiLib.currentScreen function The screen that is currently open, on every supported Minecraft version. Copy fun currentScreen(): Screen?"},{"t":"GuiLib.runOnUi","u":"getting-started.html#guilib-runonui","k":"function","s":"Runs a block on the client (render) thread. State setters are already thread-safe; use this for other work such as opening screens from a ne","c":"","b":"# GuiLib.runOnUi function Runs a block on the client (render) thread. State setters are already thread-safe; use this for other work such as opening screens from a network callback. Copy fun runOnUi(block: () -> Unit)"},{"t":"Stylesheets & resources","u":"getting-started.html#stylesheets-resources","k":"Getting started","s":"","b":"CSS files live in your mod's resources and are referenced by resource location: \"mymod:ui/app.css\" → src/main/resources/assets/mymod/ui/app.css . Several stylesheets can be passed; later ones win on equal specificity. GuiLib's built-in stylesheet ( assets/guilib/css/ua.css ) has the lowest priority, so you can override every built-in control. Images ( img , background-image: url(...) ) use resource locations too: \"mymod:textures/gui/logo.png\" (PNG, SVG or animated GIF). Invalid CSS never crashes: unknown properties and values are skipped with a warning ( file:line:col , with \"did you mean …\") in the log."},{"t":"Development workflow","u":"getting-started.html#development-workflow","k":"Getting started","s":"","b":"/guilib showcase opens a demo of every feature (the screenshots on this site are taken from it). Ctrl + F12 in any GuiLib screen shows the metrics overlay . In a dev environment CSS files are hot-reloaded from src/main/resources on save, no rebuild needed. /guilib reload reloads manually. Warnings (unknown properties, invalid values, duplicate keys, hook misuse) are logged with file and line."},{"t":"Metrics overlay","u":"getting-started.html#metrics-overlay","k":"Getting started","s":"","b":"Press Ctrl + F12 in any GuiLib screen (or open it with GuiLib.open(App, metrics = true) ) for a small window with live numbers and 30-second graphs, sampled twice a second: Frame (this screen): FPS, GuiLib's time per frame split into update (styles, layout, display list) and drawing, the worst frame. Work per second: style, layout and paint passes, nodes laid out vs. reused, DOM size, paint commands. CPU and Memory (whole game): process and render-thread CPU, heap, how fast the render thread allocates, garbage collections. Leak check: old-generation memory after the last GC. Click GC now , use your UI for a while, click GC now again: the value should stay near +0 MB. Caches: glyph atlas and image caches. Drag it by its title bar; it remembers its position until the game closes. The window measures itself out: it is a separate document whose work isn't counted, so Frame, Work and DOM show your screen only (the ⓘ next to the title explains this). Turn the shortcut off with GuiLibScreen.METRICS_SHORTCUT = false ; toggle it from code with screen.showMetrics ."},{"t":"Changelog","u":"changelog.html","k":"page","s":"What changed in each GuiLib release, newest first.","b":"What changed in each GuiLib release, newest first."},{"t":"0.12.2 · unreleased","u":"changelog.html#v0-12-2","k":"Changelog","s":"","b":"Toasts with a button: toast.info(\"Event deleted\", action = ToastAction(\"Undo\") { restore() }) runs the lambda and closes the toast. See Toasts ."},{"t":"0.12.1 · 2026-10-04","u":"changelog.html#v0-12-1","k":"Changelog","s":"","b":"§k obfuscated text: drawn as random characters of about the same width that change every 50 ms, like in Minecraft; the layout keeps the real text's size. Also for Minecraft text components ( text(component) ) with the obfuscated style. See Components . Fix: borders with a different width or color per side on a rounded box ( border-left: 3px solid green on a card with border-radius ) bend around the corners like in browsers instead of stopping where the curve begins. See Differences from the web ."},{"t":"0.12.0 · 2026-10-03","u":"changelog.html#v0-12-0","k":"Changelog","s":"","b":"New page How GuiLib works : a detailed tour through the internals, from components and the reconciler over the cascade, layout and painting to drawing in Minecraft. Metrics overlay: Ctrl + F12 in any GuiLib screen (or GuiLib.open(App, metrics = true) ) shows frame time, GuiLib's work per second, CPU, memory, GC, a leak check and cache sizes with live graphs. It doesn't count itself. See Metrics overlay . Faster layout: only the parts of a screen that changed are laid out again, everything else keeps its layout. An animated or edited element no longer re-lays out the whole screen every frame (Showcase animation page: 1.4 ms → 0.4 ms per frame). Fix: the scroll size of a container counted its absolutely positioned children at their position from the previous frame (a scrollbar could flash for one frame); it now uses their current position, and positioned boxes whose containing block is further out no longer count, like browsers."},{"t":"0.11.0 · 2026-10-03","u":"changelog.html#v0-11-0","k":"Changelog","s":"","b":"accent-color recolors the checked/filled parts of controls (checkbox, radio, switch, sliders, segmented, tabs, chips) in a subtree: .panel { accent-color: #e0b04a } . See CSS . caret-color for inputs and textareas (inherited, animatable): input { caret-color: #e0b04a } . See CSS . ::placeholder : style the placeholder text of inputs and textareas, incl. :focus::placeholder . See CSS . CSS filter : grayscale() , sepia() , brightness() , contrast() , saturate() , hue-rotate() , invert() , opacity() , blur() and drop-shadow() , on the element and everything inside it, animatable ( filter: grayscale(1) → none on hover). Color functions work on everything GuiLib draws; blur() and drop-shadow() on boxes and images (text stays sharp). See CSS . aspect-ratio , outline / outline-offset (follows border-radius , great for :focus-visible rings), text-transform , word-break / overflow-wrap (break long names and URLs), line-clamp / -webkit-line-clamp (N lines with \"…\"). See CSS . background-size ( cover , contain , lengths), background-position (keywords, %, right 10px bottom 5px ), background-repeat ( repeat-x , space , round …), background-origin and background-clip , all per layer and in the background shorthand: background: url(\"mymod:bg.png\") center / cover no-repeat . Without any of size, position and repeat a layer is still stretched over the box as before. See CSS . Tables: table , thead , tbody , tfoot , tr , th , td , caption , col , colgroup with browser-like column sizing, colSpan / rowSpan , border-collapse , border-spacing , table-layout: fixed , caption-side and vertical-align in cells. Rows have boxes, so tr:hover and zebra rows work. See Tables . Turn off Minecraft's background blur per screen: GuiLib.open(App, blurBackground = false) , or live from a component with useBackgroundBlur(enabled) (e.g. a settings switch). The dark overlay stays. See useBackgroundBlur ."},{"t":"0.10.0 · 2026-10-03","u":"changelog.html#v0-10-0","k":"Changelog","s":"","b":"Every color of the built-in controls is now a --guilib-* variable ( --guilib-button , --guilib-surface-3 , --guilib-text-subtle , --guilib-danger …). A theme only overrides variables on :root instead of the control rules; the defaults look the same as before. See Theming built-in controls . SVG images can be tinted from CSS: currentColor inside the SVG is the element's color (for img and background-image ), so one icon file works on light and dark backgrounds and follows :hover . See Tinting SVG icons . border-style: dashed and dotted are drawn (before, they were drawn solid): Chrome-like dash spacing, round dots, rounded corners supported. Handy for drop zones: border: 1px dashed var(--guilib-text-subtle) . option(…, title = \"…\") : hover text for single entries of select , multiSelect , radioGroup , segmented and chips . Fix: title tooltips are drawn above open menus and dropdowns instead of behind them. numberInput : Ctrl (Cmd) steps × 100 and Ctrl + Shift × 1000 (Shift stays × 10), for the buttons, arrow keys and the wheel; holding a button repeats with the multiplier of the press. Own factors with stepMultiplier = { modifiers -> … } . numberInput understands shorthand: type 100k , 1.5m , 2,5k or 1b (k / m / b = thousand / million / billion, . or , as decimal mark). The field keeps the text while you type and shows the number on blur or Enter; min/max and rounding apply as usual. Own formats with parse = { text -> … } . Fix: tooltips, title tips, select / multiSelect menus and the color popover no longer get cut off at the screen edges (small windows, high GUI scale): they flip to the other side when only that fits and are shifted inside the screen. option(…, className = \"legendary\", style = \"color: #ffaa00\") for select / multiSelect (and radioGroup , segmented , chips ): the class / style goes on the menu entry and on the chosen label in the box, so item names can be colored in the open list and in a multiple selection. The box now shows one span.guilib-select-chosen per chosen entry."},{"t":"0.9.0 · 2026-10-03","u":"changelog.html#v0-9-0","k":"Changelog","s":"","b":"Minecraft 26.3 support: artifact net.sbo:guilib-26.3-fabric . Everything works the same as on 26.1.2 / 26.2 (typing, shortcuts, IME, cursors, shaders). On 26.3 KeyboardEvent.keyCode is Minecraft's new raw key code (an SDL scancode instead of a GLFW key code). Compare key ( \"Enter\" , \"a\" …) instead, which is the same on every version."},{"t":"0.8.1 · 2026-10-02","u":"changelog.html#v0-8-1","k":"Changelog","s":"","b":"Fix: crash Scissor size must be >0, was 0x0 when an element with its own clip ( overflow: hidden/auto , e.g. a scroll box) was scrolled completely out of view inside another scroll container (0.8.0 only)."},{"t":"0.8.0 · 2026-10-02","u":"changelog.html#v0-8-0","k":"Changelog","s":"","b":"useAsync { … } , useFuture { … } and usePromise { resolve, reject -> … } : load data in the background (HTTP, files) and render loading / value / error , with reload() ; outdated results are dropped. Faster rendering (2-8x less time per frame on big screens): GuiLib adds its elements to Minecraft's GUI layers directly instead of through Minecraft's overlap search (which got slow with many elements), gradients are cached instead of rebuilt on every repaint, animated screens are laid out and painted once per frame instead of twice, and drawn text no longer allocates every frame. Fix: a finished @keyframes animation no longer plays again whenever its element is restyled (hover, class or inline style changes). Sortable items with an entry animation jumped back to their old place over and over while being dragged."},{"t":"0.7.0 · 2026-10-02","u":"changelog.html#v0-7-0","k":"Changelog","s":"","b":"Fix: textarea(rows = n) is exactly n lines tall (it was slightly too short, so n lines already showed a scrollbar), also with custom padding or borders. Fix: the textarea caret and selection were 1px off (right and down) when the field has a border. Fix: text-align: center / right on input and textarea : the caret, the selection and mouse clicks now follow the aligned text (before only the text moved). Fix: entity(...) models were drawn at the wrong place (or not at all) with an own screen scale ( useScreenScale , GuiLib.open(…, scale = …) ). Grid repeat(auto-fit, …) now collapses empty repeated tracks like browsers (before it behaved like auto-fill ), so a few items stretch over the whole row. Scrollbars that hide when idle: add the class guilib-autohide to a scroll container; it fades out 600 ms after scrolling stops and comes back on scroll or hover. Built on the new GuiLib-only pseudo-class :scrolling , which you can use for your own effects. :nth-child(An+B of S) / :nth-last-child(… of S) : count only siblings matching a selector list, e.g. zebra rows that skip hidden ones with .row:nth-child(even of :not(.hidden)) . Fix: sibling selectors like .a:hover + .b or .a.active ~ .b now update when the earlier sibling's state or classes change. Own GUI scale per screen: useScreenScale(2.5f) / GuiLib.open(…, scale = …) , independent of Minecraft's, also fractional; everything incl. portals is laid out and drawn with it, text stays sharp, vw / vh and @media (resolution) follow, changes apply live. Fix: text is re-measured when the GUI scale changes even if no style changes (widths snap to the new pixel grid). @supports with (property: value) , selector(…) , not / and / or (true when GuiLib can parse it), for CSS fallbacks. useBodyClass / useBodyStyle and DOM-like classList.add/remove/toggle , setStyleProperty on elements (and GuiLib.currentDocument() ): switch a theme or font at runtime without reopening the screen. @font-face in stylesheets: declare your own TTF/OTF fonts ( src: url(\"mymod:fonts/x.ttf\") , font-weight incl. ranges, font-style ). sortableList(group = …) : an item can be dropped anywhere in a list's column (below a short list, or into an empty list without a min-height ). Fix: sortable items with their own margins (e.g. one item with margin-top ) no longer make the other items shift by the wrong distance while dragging. Fix: the first SVG image no longer freezes the game for ~0.1 s; SVG support is warmed up in the background at startup."},{"t":"0.6.0 · 2026-10-02","u":"changelog.html#v0-6-0","k":"Changelog","s":"","b":"item(stack, tooltip = true) : shows Minecraft's item tooltip while the icon is hovered, like in an inventory. sortableList(exitMs = 200) : removed items stay in place with .leaving so CSS can animate them out. sub / sup tags and vertical-align on inline elements: text can be raised or lowered (H₂O, mc², footnotes). Fix: big animated GIFs no longer freeze the game for a moment when they first appear; they are decoded in the background."},{"t":"0.5.0 · 2026-10-02","u":"changelog.html#v0-5-0","k":"Changelog","s":"","b":"presenceList(items, key, exitMs) { item, leaving -> } : removed list items animate out at their old position. ::before and ::after with content (strings, attr() ): generated boxes that can be styled, positioned and animated like elements. text(component) : show_item hover events (item links like stack.displayName ) show Minecraft's item tooltip; show_entity shows the entity info with advanced tooltips (F3+H), like in chat. cursor: none hides the mouse cursor over an element (e.g. to draw a custom one). letter-spacing (lengths incl. em and negative values, animatable), for the TTF and the Minecraft font. vertical-align for inline-block boxes, images and items: baseline middle top bottom text-top text-bottom sub super and lengths. align-content and place-content for wrapping flex containers and grids (rows). A wrapping flex container with a fixed height now stretches its lines by default ( normal ), like browsers; use align-content: flex-start for the old packing. conic-gradient (with an animatable from angle) and repeating-linear-gradient / repeating-radial-gradient / repeating-conic-gradient (stripes, rings, pie charts, checkerboards). Fix: hard color stops in radial-gradient ( white 10px, black 10px ) are sharp again instead of fading to the next ring."},{"t":"0.4.3 · 2026-10-02","u":"changelog.html#v0-4-3","k":"Changelog","s":"","b":"Fix: select (also searchable / multiSelect ), colorInput and tooltip popups stay attached to their element when the window is resized or moved to another monitor. An open contextMenu closes on a viewport change, like in browsers. numberInput(allowEmpty = true) : + on an empty field starts at step (at least min ), − on an empty field does nothing, − at min empties the field again."},{"t":"0.4.2 · 2026-10-01","u":"changelog.html#v0-4-2","k":"Changelog","s":"","b":"Fix: an element with both height and max-height (or min-height ) now gives its children the clamped height, like the web. A flex: 1 scroll body inside a max-height panel no longer overflows it."},{"t":"0.4.1 · 2026-10-01","u":"changelog.html#v0-4-1","k":"Changelog","s":"","b":"useClipboard() to read and write the system clipboard (safe to call from any thread). numberInput(value: Int?/Double?, allowEmpty = true) : the field may be empty ( null ). textarea(maxLines = …) . playerHead(player, hat = true) draws a player's face from a name, UUID, profile or player."},{"t":"0.4.0 · 2026-10-01","u":"changelog.html#v0-4-0","k":"Changelog","s":"","b":"box-shadow (blur, spread, inset, several layers, animatable). @media queries: width/height, orientation, aspect-ratio, resolution (= GUI scale), hover/pointer, range syntax, nesting. Inline elements ( span , code , …) paint background, border and shadow per line; their horizontal padding/border take space. text(component) renders Minecraft Component s with colors, styles, hover text and click events; useTranslation() for translation keys with live language switching. sortableList : drag between lists ( group ), auto-scroll near scroll edges, Alt + arrow keys move items. New :focus-visible . Animated GIFs in img and background-image . cursor: grab / grabbing / row-resize / col-resize with real hand cursors; drag cursors stay while the button is held. Smoother rotated and skewed text. Fix: a cancelled transition (e.g. dropping a sortable item quickly) no longer leaves a stale offset."},{"t":"0.3.0 · 2026-10-01","u":"changelog.html#v0-3-0","k":"Changelog","s":"","b":"New controls: switch , slider , rangeSlider , numberInput , radioGroup , segmented , chips , tabs , details / collapse , contextMenu , useToast() , searchable select , multiSelect , textarea . Fix: positioned elements no longer escape the clip of a scroll container."},{"t":"0.2.1 · 2026-10-01","u":"changelog.html#v0-2-1","k":"Changelog","s":"","b":"transform : translate, scale, rotate, skew, matrix (animatable, hit-testing follows the shape). presence() for exit animations. :nth-child() , :nth-last-child() , :nth-of-type() , :nth-last-of-type() . sortableList (drag to reorder). entity(...) and a fake player for rendering entities. Fixes: Shift + wheel scrolls horizontally in game; horizontal-only scroll containers scroll with the plain wheel; § codes, selection and system clipboard in text inputs; caret stays on whole characters (emoji)."},{"t":"0.2.0 · 2026-10-01","u":"changelog.html#v0-2-0","k":"Changelog","s":"","b":"CSS grid, transitions and @keyframes , linear and radial gradients (several background layers), calc() / min() / max() / clamp() . colorPicker and colorInput . Per-side borders on rounded boxes; child backgrounds in the corners of a rounded clip are rounded too."},{"t":"0.1.1 · 2026-10-01","u":"changelog.html#v0-1-1","k":"Changelog","s":"","b":"Development tooling is no longer part of the published jar."},{"t":"0.1.0 · 2026-09-30","u":"changelog.html#v0-1-0","k":"Changelog","s":"","b":"First release: components and hooks, CSS cascade and variables, box model, block/inline flow, flexbox, positioning, rounded corners, TTF text (Inter), PNG/SVG images, input, checkbox, select, tooltip, modal, portals, CSS hot reload."},{"t":"Components & hooks","u":"components.html","k":"page","s":"UIs are built from function components. Hooks give them state, effects and access to the document, exactly like React.","b":"UIs are built from function components. Hooks give them state, effects and access to the document, exactly like React."},{"t":"Components","u":"components.html#components","k":"Components & hooks","s":"","b":"Render a component inside any DSL block by calling it: Name(props, key = …) or Name(key = …) for components without props. The name shows up in warnings and error messages."},{"t":"component","u":"components.html#component","k":"function","s":"Declares a function component. The render lambda runs with a ComponentScope receiver (hooks + DSL) and receives the props. Use a data class ","c":"","b":"# component function Declares a function component. The render lambda runs with a ComponentScope receiver (hooks + DSL) and receives the props. Use a data class for props so unchanged props skip re-rendering. Copy fun <P> component(name: String, render: ComponentScope.(props: P) -> Unit): ComponentType<P> fun component(name: String, render: ComponentScope.() -> Unit): ComponentType<Unit> Example Copy data class BadgeProps(val text: String, val color: String) val Badge = component<BadgeProps>(\"Badge\") { props -> span(className = \"badge\", style = \"background-color: ${props.color}\") { +props.text } } val Header = component(\"Header\") { div(className = \"header\") { Badge(BadgeProps(\"NEW\", \"#3ba55d\")) // render a component Badge(BadgeProps(\"M7\", \"#ed4245\"), key = \"m7\") // with a key } }"},{"t":"Keys & lists","u":"components.html#keys-lists","k":"Components & hooks","s":"","b":"When rendering lists, give every item a stable key (any value with a sensible equals ). Keys let GuiLib keep the right state, focus and animations attached to the right item when the list changes, exactly like React. Copy for (party in parties) PartyRow(party, key = party.id) for (name in names) div(key = name) { +name }"},{"t":"Text","u":"components.html#text","k":"Components & hooks","s":"","b":"Add text with +\"text\" or text(value) (any value, converted with toString() ). Minecraft § color and format codes work in all text: +\"§6Gold §lbold\" . §k (since 0.12.1) draws the text as random characters that keep changing, like Minecraft's obfuscated text, while it keeps the real text's size: +\"§kSecret\" ; §r or a color code ends it. Copy span { +\"Hello \" ; b { +name } ; text(count) }"},{"t":"Classes","u":"components.html#classes","k":"Components & hooks","s":"","b":"className works like HTML's class attribute: several classes are separated by spaces . Commas don't separate classes, \"a, b\" would give the class a, (with the comma), so .a wouldn't match. Copy div(className = \"card\") // one class div(className = \"card selected big\") // three classes: .card, .selected, .big div(className = \"a, b\") // wrong: classes \"a,\" and \"b\""},{"t":"Helper functions (NodeBuilder)","u":"components.html#helper-functions-nodebuilder","k":"Components & hooks","s":"","b":"Every { } block of the DSL is a NodeBuilder , and all tags ( div , span , button , …) are extension functions on it. To move part of a UI into its own function, declare the function on NodeBuilder too. Call it inside any block and the elements it creates end up there. Parameters decide what it renders. Copy import net.sbo.guilib.core.dsl.NodeBuilder fun NodeBuilder.renderGraph(values: List<Int>) { div(className = \"graph\") { for (v in values) div(className = \"bar\", style = \"height: ${v}px\") } } val App = component(\"App\") { div(className = \"window\") { div(className = \"body\") { renderGraph(listOf(10, 40, 25)) // the graph is placed inside .body } } } A plain fun renderGraph() = div { … } doesn't compile: without the NodeBuilder. receiver there is no block to add the element to. Helper or component? A helper is just code that runs as part of the caller's render. It can't use hooks ( useState , useEffect , useAsync , …) and re-renders whenever the caller does. As soon as a part needs its own state or effects, or should skip re-rendering when its data hasn't changed, make it a component instead."},{"t":"State","u":"components.html#state","k":"Components & hooks","s":"","b":""},{"t":"useState","u":"components.html#usestate","k":"hook","s":"Local state. Use it as a delegate or destructure it like React. Assigning a different value re-renders the component. Setters may be called ","c":"","b":"# useState hook Local state. Use it as a delegate or destructure it like React. Assigning a different value re-renders the component. Setters may be called from any thread (they are posted to the UI thread). Copy fun <T> useState(initial: T): State<T> Example Copy var count by useState(0) // delegate count++ val (name, setName) = useState(\"\") // destructuring setName(\"Steve\") val tasks = useState(listOf<String>()) // State object tasks.update { it + \"new task\" } // functional update tasks.value // current value"},{"t":"useStateLazy","u":"components.html#usestatelazy","k":"hook","s":"State whose initial value is computed only on the first render.","c":"","b":"# useStateLazy hook State whose initial value is computed only on the first render. Copy fun <T> useStateLazy(initial: () -> T): State<T>"},{"t":"useRef","u":"components.html#useref","k":"hook","s":"A mutable box kept across renders. Changing current does not re-render. Good for timers, previous values and drag state.","c":"","b":"# useRef hook A mutable box kept across renders. Changing current does not re-render. Good for timers, previous values and drag state. Copy fun <T> useRef(initial: T): Ref<T>"},{"t":"useElementRef","u":"components.html#useelementref","k":"hook","s":"A ref for an element. Pass it as ref = to any tag; ref.current is then the Element (bounding rect, focus, scroll position, …).","c":"","b":"# useElementRef hook A ref for an element. Pass it as ref = to any tag; ref.current is then the Element (bounding rect, focus, scroll position, …). Copy fun useElementRef(): Ref<Element?> Example Copy val input = useElementRef() input(ref = input, value = text, onChange = { text = it.value }) button(onClick = { input.current?.focus() }) { +\"Focus\" }"},{"t":"useMemo","u":"components.html#usememo","k":"hook","s":"Caches a computed value until one of the dependencies changes ( == ).","c":"","b":"# useMemo hook Caches a computed value until one of the dependencies changes ( == ). Copy fun <T> useMemo(vararg deps: Any?, compute: () -> T): T Example Copy val sorted = useMemo(parties) { parties.sortedBy { it.leader } }"},{"t":"Effects","u":"components.html#effects","k":"Components & hooks","s":"","b":""},{"t":"useEffect","u":"components.html#useeffect","k":"hook","s":"Runs a side effect after the DOM was updated.","c":"","b":"# useEffect hook Runs a side effect after the DOM was updated. Without deps it runs once after mount (like React's useEffect(fn, []) ). With deps it runs after mount and whenever one of them changes. There is no \"after every render\" variant. Copy fun useEffect(vararg deps: Any?, effect: EffectScope.() -> Unit) Inside the effect: onCleanup { } registers cleanup, setTimeout(ms) { } and setInterval(ms) { } create timers that are cancelled on cleanup or unmount. Example Copy useEffect { // once val task = setInterval(1000) { seconds++ } // cancelled automatically on unmount onCleanup { println(\"closed\") } } useEffect(partyId) { // whenever partyId changes loadParty(partyId) { setParty(it) } }"},{"t":"useInterval","u":"components.html#useinterval","k":"hook","s":"Calls the callback every ms milliseconds while mounted. Always calls the latest lambda, so it sees current state.","c":"","b":"# useInterval hook Calls the callback every ms milliseconds while mounted. Always calls the latest lambda, so it sees current state. Copy fun useInterval(ms: Long, callback: () -> Unit) Example Copy useInterval(1000) { elapsed++ }"},{"t":"useAsync","u":"components.html#useasync","k":"hook","s":"Loads data without blocking the game: runs load on a GuiLib background thread after mount and whenever one of keys changes, then re-renders ","c":"","b":"# useAsync hook Loads data without blocking the game: runs load on a GuiLib background thread after mount and whenever one of keys changes, then re-renders with the result. Returns Async<T> : loading , value (the last successful result, kept while a reload runs), error , isSuccess , reload() . Results of outdated loads (keys changed, component unmounted) are dropped. load runs on another thread: never touch the UI in it. Copy fun <T> useAsync(vararg keys: Any?, load: () -> T): Async<T> fun <T> useFuture(vararg keys: Any?, start: () -> CompletableFuture<T>): Async<T> fun <T> usePromise(vararg keys: Any?, start: (resolve: (T) -> Unit, reject: (Throwable) -> Unit) -> Unit): Async<T> useFuture does not cancel outdated futures (they may be shared); their result is ignored. usePromise ignores every call after the first resolve / reject . Example Copy val commit = useAsync { fetchLatestCommit() } // blocking HTTP call, runs in the background span { +when { commit.error != null -> \"unavailable\" commit.loading -> \"loading…\" else -> commit.value!! } } button(onClick = { commit.reload() }, disabled = commit.loading) { +\"Reload\" } // Already have a CompletableFuture? useFuture(partyId) { api.party(partyId) } // Callback-style API (like JS Promise): usePromise(floor) { resolve, reject -> api.load(floor, resolve, reject) }"},{"t":"useDocumentEvent","u":"components.html#usedocumentevent","k":"hook","s":"Listens to an event on the whole document while mounted (like document.addEventListener in an effect). Runs before element handlers; call st","c":"","b":"# useDocumentEvent hook Listens to an event on the whole document while mounted (like document.addEventListener in an effect). Runs before element handlers; call stopPropagation() / preventDefault() to swallow the event. Copy fun useDocumentEvent(type: String, listener: (UIEvent) -> Unit) Example Copy useDocumentEvent(\"keydown\") { e -> if ((e as KeyboardEvent).key == \"r\") refresh() }"},{"t":"Context","u":"components.html#context","k":"Components & hooks","s":"","b":""},{"t":"createContext","u":"components.html#createcontext","k":"function","s":"Creates a context with a default value, for passing data deep into the tree without props (themes, the current user, …).","c":"","b":"# createContext function Creates a context with a default value, for passing data deep into the tree without props (themes, the current user, …). Copy fun <T> createContext(defaultValue: T, name: String = \"Context\"): Context<T> Example Copy val ThemeCtx = createContext(\"dark\") val App = component(\"App\") { ThemeCtx.Provider(\"light\") { Toolbar() } } val Toolbar = component(\"Toolbar\") { val theme = useContext(ThemeCtx) div(className = \"toolbar $theme\") { … } }"},{"t":"useContext","u":"components.html#usecontext","k":"hook","s":"Reads the value of the nearest Provider above, or the context's default. The component re-renders when the provided value changes.","c":"","b":"# useContext hook Reads the value of the nearest Provider above, or the context's default. The component re-renders when the provided value changes. Copy fun <T> useContext(context: Context<T>): T"},{"t":"Translations","u":"components.html#translations","k":"Components & hooks","s":"","b":""},{"t":"useTranslation","u":"components.html#usetranslation","k":"hook","s":"Translates keys from the game's language files ( assets/<modid>/lang/<lang>.json ) like I18n.get . The component re-renders when the languag","c":"","b":"# useTranslation hook Translates keys from the game's language files ( assets/<modid>/lang/<lang>.json ) like I18n.get . The component re-renders when the language changes or resource packs reload. Missing keys return the key. t.language is the language code ( en_us ), t.has(key) checks a key. Import from net.sbo.guilib.fabric . Copy fun useTranslation(): Translator Example Copy val t = useTranslation() h1 { +t(\"mymod.gui.title\") } p { +t(\"mymod.gui.kills\", kills) } // \"Kills: %s\" text(Component.translatable(\"mymod.gui.hint\").withStyle(ChatFormatting.GRAY))"},{"t":"Document & misc","u":"components.html#document-misc","k":"Components & hooks","s":"","b":""},{"t":"useDocument","u":"components.html#usedocument","k":"hook","s":"The Document of the screen: viewportWidth / viewportHeight , focusedElement , focus(el) , addEventListener , setTimeout / setInterval , post","c":"","b":"# useDocument hook The Document of the screen: viewportWidth / viewportHeight , focusedElement , focus(el) , addEventListener , setTimeout / setInterval , post { } . Copy fun useDocument(): Document"},{"t":"useScreenScale","u":"components.html#usescreenscale","k":"hook","s":"Gives the screen its own GUI scale while the component is mounted, independent of Minecraft's ( null = Minecraft's, fractions like 2.5f work","c":"","b":"# useScreenScale hook Gives the screen its own GUI scale while the component is mounted, independent of Minecraft's ( null = Minecraft's, fractions like 2.5f work). The whole document is laid out and drawn with it, portals (modals, tooltips, menus, toasts) included: the viewport is the window size / scale, vw / vh and @media (resolution) follow, text and SVGs are re-rasterized for the new pixel size so they stay sharp. Changing it re-lays out at once, without reopening. Restored on unmount. Outside components: GuiLib.currentDocument()?.scale = 2.5f . Note: the minecraft font is a pixel font and looks uneven at fractional scales; Minecraft's own item tooltips keep Minecraft's scale. Copy fun useScreenScale(scale: Float?) Example Copy var scale by useState<Float?>(null) useScreenScale(scale) // Apply on release: rescaling while the slider is dragged would move it under the mouse. slider(value = scale ?: 2f, min = 1f, max = 4f, step = 0.25f, onChangeEnd = { scale = it }, showValue = true) button(onClick = { scale = null }) { +\"Minecraft scale\" }"},{"t":"useBackgroundBlur","u":"components.html#usebackgroundblur","k":"hook","s":"Turns Minecraft's blur behind the screen on or off while the component is mounted; the dark overlay stays (open with vanillaBackground = fal","c":"","b":"# useBackgroundBlur hook Turns Minecraft's blur behind the screen on or off while the component is mounted; the dark overlay stays (open with vanillaBackground = false to drop both). Changes apply at once, so it can be bound to a settings switch. Restored on unmount. Also GuiLib.open(App, blurBackground = false) ; outside components: GuiLib.currentDocument()?.backgroundBlur = false . Copy fun useBackgroundBlur(enabled: Boolean) Example Copy var blur by useState(settings.blurBackground) useBackgroundBlur(blur) switch(checked = blur, onChange = { blur = it.checked }, label = \"Blur background\")"},{"t":"useBodyClass","u":"components.html#usebodyclass","k":"hook","s":"Puts a class on the body while the component is mounted and enabled , e.g. a theme or font switch without reopening the screen. Portals (mod","c":"","b":"# useBodyClass hook Puts a class on the body while the component is mounted and enabled , e.g. a theme or font switch without reopening the screen. Portals (modals, tooltips, toasts) live under the body, so they follow too. Removed again on unmount. Copy fun useBodyClass(className: String, enabled: Boolean = true) Example Copy // CSS: body.font-mc { font-family: minecraft } useBodyClass(\"font-mc\", settings.minecraftFont)"},{"t":"useBodyStyle","u":"components.html#usebodystyle","k":"hook","s":"Sets one inline property or CSS variable on the body while mounted ( null sets nothing). Inherited properties and variables reach every elem","c":"","b":"# useBodyStyle hook Sets one inline property or CSS variable on the body while mounted ( null sets nothing). Inherited properties and variables reach every element. Copy fun useBodyStyle(property: String, value: String?) Example Copy useBodyStyle(\"--accent\", accentColor) // CSS: .button { background: var(--accent) }"},{"t":"Element.classList / setStyleProperty","u":"components.html#element-classlist-setstyleproperty","k":"function","s":"Change an element's classes and inline style like in the DOM: classList.add(…) , remove(…) , toggle(name, force) , replace(old, new) , inlin","c":"","b":"# Element.classList / setStyleProperty function Change an element's classes and inline style like in the DOM: classList.add(…) , remove(…) , toggle(name, force) , replace(old, new) , inlineStyle = \"…\" , setStyleProperty(name, value) , removeStyleProperty(name) , getStyleProperty(name) . Meant for useDocument().body ; from outside the UI use GuiLib.currentDocument()?.body on the render thread. On an element you render with className / style , the next render sets them back (like React). Copy val classList: ClassList // Set<String> + add / remove / toggle / replace var inlineStyle: String? fun setStyleProperty(property: String, value: String?) fun removeStyleProperty(property: String) fun getStyleProperty(property: String): String? fun GuiLib.currentDocument(): Document? Example Copy // After a config change, outside any component: GuiLib.runOnUi { GuiLib.currentDocument()?.body?.classList?.toggle(\"font-mc\", config.minecraftFont) }"},{"t":"useToast","u":"components.html#usetoast","k":"hook","s":"The toaster of this screen, for short notifications. See Toasts .","c":"","b":"# useToast hook The toaster of this screen, for short notifications. See Toasts . Copy fun useToast(): Toaster"},{"t":"useClipboard","u":"components.html#useclipboard","k":"hook","s":"The system clipboard, e.g. for a \"Copy note\" button. set(text) is safe to call from any thread; call get() on the UI thread (event handlers,","c":"","b":"# useClipboard hook The system clipboard, e.g. for a \"Copy note\" button. set(text) is safe to call from any thread; call get() on the UI thread (event handlers, effects). The same object as useDocument().clipboard . Copy fun useClipboard(): Clipboard interface Clipboard { fun get(): String; fun set(text: String) } Example Copy val clipboard = useClipboard() val toast = useToast() button(onClick = { clipboard.set(note); toast.success(\"Note copied\") }) { +\"Copy note\" }"},{"t":"useForceUpdate","u":"components.html#useforceupdate","k":"hook","s":"Returns a function that re-renders the component. An escape hatch; prefer state.","c":"","b":"# useForceUpdate hook Returns a function that re-renders the component. An escape hatch; prefer state. Copy fun useForceUpdate(): () -> Unit"},{"t":"classNames","u":"components.html#classnames","k":"function","s":"Joins class names and skips falsy ones, like the clsx package.","c":"","b":"# classNames function Joins class names and skips falsy ones, like the clsx package. Copy fun classNames(vararg parts: Any?): String Example Copy div(className = classNames(\"tab\", \"active\" to isActive, extraClass)) { … }"},{"t":"Rules of hooks","u":"components.html#rules-of-hooks","k":"Components & hooks","s":"","b":"Call hooks unconditionally at the top of the component, not inside div { } blocks, loops or if s. Hook misuse (a different number or order of hooks between renders) is detected and logged. Hooks are extension functions on ComponentScope , so they're only callable inside component render lambdas."},{"t":"Differences from the web","u":"differences.html","k":"page","s":"GuiLib follows the web wherever it can. These are the places where it doesn't. Read this once; it saves time.","b":"GuiLib follows the web wherever it can. These are the places where it doesn't. Read this once; it saves time."},{"t":"Units & defaults","u":"differences.html#units-defaults","k":"Differences from the web","s":"","b":"px means GUI pixels (scaled by Minecraft's GUI scale). The default font-size is 8px and 1rem = 8px , so a web value like font-size: 14px is large here; typical UI text is 7–10px. body is the screen : always exactly viewport-sized; there is no html ; :root matches body . box-sizing: border-box is the default for everything. No margin collapsing : vertical margins add up. The default text color is light ( #f2f3f5 ), the default font Inter. border-width defaults to 1px; like the web, a border without border-style draws nothing."},{"t":"API","u":"differences.html#api","k":"Differences from the web","s":"","b":"style is a CSS string , not an object. Event handlers are Kotlin lambdas ( onClick = { e -> … } ). useEffect { } without deps runs once (like [] ); there is no \"run after every render\" variant. onChange on inputs, selects, checkboxes, switches and sliders fires on every change (React behaviour); sliders also have onChangeEnd ."},{"t":"Rendering","u":"differences.html#rendering","k":"Differences from the web","s":"","b":"overflow: hidden clips rectangularly . With border-radius on the clipping element, child backgrounds that sit exactly in one of its corners (headers, footers, sidebars) are rounded to match; other content is not cut to the curve. Per-side borders on a box with border-radius (since 0.12.1) bend around the corners and meet on the diagonal like in browsers; the inner corner is circular (browsers: elliptical when the two widths differ), and sides wider than 15.5px fall back to straight strips that stop at the rounded corners. dashed / dotted follow Chrome's look (dash 3× the width, a dash in each square corner). Rounded corners of a uniform dashed border are solid arcs; double groove ridge inset outset are not supported (skipped with a warning). Inline elements ( span , code , …) paint background, border and shadow per line like the web; vertical padding/border don't change the line height. Use display: inline-block for boxes that must not wrap or need a size. Every positioned element ( relative / absolute / fixed ) is its own paint layer; z-index orders layers among siblings. Use portal { } for things that must be on top of everything. position: fixed ignores ancestors' transform . vertical-align: top / bottom on display: inline elements act like text-top / text-bottom (aligned to the parent's text, not to the line box). Flex items have min-width: auto like the web; for ellipsis inside flex, set min-width: 0 ."},{"t":"Text","u":"differences.html#text","k":"Differences from the web","s":"","b":"Minecraft § codes work in all text. Text inputs show what the user types literally ( § included). No kerning; text-align: justify behaves like left . No right-to-left or complex-script shaping. Characters missing from the font (CJK, emoji, …) fall back to Minecraft's font. Rotated or skewed text is rasterized at 2× and filtered: smooth, but a little softer than straight text."},{"t":"Not supported (yet)","u":"differences.html#not-supported-yet","k":"Differences from the web","s":"","b":"3D transforms (a transform containing them is ignored). @import , pseudo-elements other than ::before / ::after / ::placeholder . float , subgrid, named grid lines. Backgrounds: a url() or gradient layer without background-size / -position / -repeat is stretched over the box (browsers: natural size, tiled). Copies of a positioned or tiled layer have square corners ( border-radius doesn't cut them). filter : blur() keeps text and gradients sharp and drop-shadow() of text isn't blurred (there is no offscreen pass: each box, text run and image is filtered on its own); items, entities, player heads and animated GIFs aren't filtered; url() SVG filters and backdrop-filter aren't supported. Tables: col backgrounds, visibility: collapse , empty-cells . A rowspan cell is painted before the later rows it covers, so their backgrounds hide its lower part. Collapsed borders keep the color of the cell painted last. Images are resource locations (PNG, SVG or GIF), no URLs. currentColor inside an SVG image is the element's CSS color (browsers use black for <img> SVGs)."},{"t":"Recipes","u":"recipes.html","k":"page","s":"Short answers to common UI tasks.","b":"Short answers to common UI tasks."},{"t":"Layout","u":"recipes.html#layout","k":"Recipes","s":"","b":"Task How Full-screen centered panel body { display: flex; align-items: center; justify-content: center } + a sized child Scrollable list filling the rest Parent display: flex; flex-direction: column; height: … , list flex-grow: 1; min-height: 0; overflow: auto Ellipsis white-space: nowrap; overflow: hidden; text-overflow: ellipsis (+ min-width: 0 in flex rows) Responsive tiles display: grid; grid-template-columns: repeat(auto-fill, minmax(60px, 1fr)); gap: 4px ( auto-fit collapses empty columns so a few tiles stretch) Sidebar + content display: grid; grid-template-columns: 80px 1fr (or grid-template-areas ) Horizontal scroll row display: flex; overflow-x: auto; overflow-y: hidden with flex-shrink: 0 on the children Scrollbar that hides when idle scroll(className = \"list guilib-autohide\") ; color: .list { --guilib-scrollbar-thumb: #5b8def } Zebra rows .row:nth-child(even) { background-color: #2b2d31 } ; skipping hidden rows: .row:nth-child(even of :not(.hidden)) Theme Define --vars on :root in one CSS file and use var(--x) everywhere"},{"t":"Behaviour","u":"recipes.html#behaviour","k":"Recipes","s":"","b":"Task How Close button button(onClick = { GuiLib.close() }) { +\"✕\" } Async data val r = useAsync { slowCall() } → show r.loading / r.error / r.value , r.reload() to refresh; useFuture / usePromise for futures and callback APIs Keyboard shortcut for the screen useDocumentEvent(\"keydown\") { e -> if ((e as KeyboardEvent).key == \"r\") refresh() } Feedback after an action val toast = useToast() → toast.success(\"Saved\") Save a setting once, not while dragging slider(..., onChangeEnd = { config.save() }) Only one accordion item open details(open = openId == id, onToggle = { openId = if (it) id else null }) Reorderable list sortableList(tasks, key = { it.id }, onReorder = { tasks = it }) { task, _ -> div { +task.name } }"},{"t":"Animation","u":"recipes.html#animation","k":"Recipes","s":"","b":"Task How Hover fade .card { transition: background-color 150ms } .card:hover { background-color: #333 } Fade in on open @keyframes fade-in { from { opacity: 0 } } + .panel { animation: fade-in 200ms ease-out } Staggered slide-in .item { animation: slide-in 300ms ease-out backwards } and style = \"animation-delay: ${i * 50}ms\" Slide out before removal presence(visible = open, exitMs = 200) { leaving -> … } + .leaving { animation: slide-out 200ms forwards } Animate removed list rows presenceList(rows, key = { it.id }, exitMs = 200) { row, leaving -> … } + .leaving { animation: row-out 200ms forwards } Animate removed sortable rows sortableList(…, exitMs = 200) + .my-list .guilib-sortable-item.leaving { animation: row-out 200ms forwards } Grow on hover .card { transition: transform 150ms ease-out } .card:hover { transform: scale(1.05) } Spinner @keyframes spin { to { transform: rotate(360deg) } } + .spinner { animation: spin 1s linear infinite } Animated height collapse(open = expanded) { … } (or details )"},{"t":"A complete example","u":"recipes.html#a-complete-example","k":"Recipes","s":"","b":"A small party finder screen combining several controls: Copy val PartyFinder = component(\"PartyFinder\") { var category by useState(\"dungeons\") var size by useState(\"5\") var minCata by useState(30) var note by useState(\"\") val toast = useToast() div(className = \"finder\") { tabs(value = category, onChange = { category = it }) { tab(\"dungeons\", \"Dungeons\"); tab(\"kuudra\", \"Kuudra\"); tab(\"fishing\", \"Fishing\") } div(className = \"form-row\") { span { +\"Size\" } segmented(value = size, onChange = { size = it }) { option(\"2\", \"Duo\"); option(\"3\", \"Trio\"); option(\"5\", \"Full\") } } div(className = \"form-row\") { span { +\"Min. cata\" } numberInput(value = minCata, onChange = { minCata = it }, min = 0, max = 50) } textarea(value = note, onChange = { note = it.value }, placeholder = \"Note\", rows = 2, maxLength = 120) button(className = \"primary\", onClick = { api.createParty(category, size.toInt(), minCata, note, onSuccess = { toast.success(\"Party created\") }, onError = { toast.error(it, title = \"Party finder\") }) }) { +\"Create party\" } } }"},{"t":"How GuiLib works","u":"internals.html","k":"page","s":"A detailed tour through GuiLib's internals: what happens between GuiLib.open(App) and the pixels on screen, and why. You don't need any of t","b":"A detailed tour through GuiLib's internals: what happens between GuiLib.open(App) and the pixels on screen, and why. You don't need any of this to build UIs, but it explains every behaviour you'll observe, helps with performance questions and is the map for reading or contributing to the source."},{"t":"The big picture","u":"internals.html#big-picture","k":"How GuiLib works","s":"","b":"GuiLib is a small browser engine. It has the same stages as a real one, scaled down to what game UIs need, and it draws through Minecraft's GUI renderer instead of a window of its own: The pipeline Copy Kotlin DSL div(className = \"card\") { +\"Hi\" } │ your code; runs on every render ▼ Virtual nodes VElement(\"div\", props, [VText(\"Hi\")]) │ cheap and immutable; rebuilt each render │ reconciler: diff against the mounted tree ▼ DOM Element(\"div\") ── TextNode(\"Hi\") │ long-lived; patched in place │ style engine: selectors, cascade, inheritance, var() ▼ Computed styles one ComputedStyle per element (typed values) │ animator: transitions and @keyframes write in-between values ▼ Layout one LayoutBox per node (position, size, lines) │ painter: stacking order, clips, transforms, opacity ▼ Display list [Box, Text, Image, Gradient, PushClip, …] + hit regions │ command renderer (Fabric backend) ▼ Minecraft GUI render states + GuiLib's shaders Every stage only does work when something it depends on changed. A UI that sits still costs almost nothing per frame: no styles are computed, nothing is laid out, the display list from the last change is drawn again. The library is split in two halves: Part Package What it contains Core net.sbo.guilib.core Everything above except the last step: DSL, components and hooks, reconciler, DOM, CSS parser and style engine, animations, layout, painting, events, the built-in controls. Pure Kotlin without a single Minecraft import (a unit test enforces this), so it runs in plain JUnit tests and doesn't change between Minecraft versions. Backend net.sbo.guilib.fabric The Minecraft side: the GuiLibScreen that hosts a document, input translation, the command renderer with its shaders, fonts (FreeType), images (PNG, SVG via JSVG, GIF), items, entities, player heads, chat Component s, translations, resource loading, hot reload and the metrics overlay. Multi-version code lives here (preprocessor for 26.1.2 / 26.2 / 26.3). The glue between them is UiRoot : one Document (the tree, styles, layout, timers), one Painter (display list and hit regions) and one InteractionController (input → events). A GuiLibScreen owns one UiRoot , feeds it Minecraft's input and calls frame() once per rendered frame."},{"t":"From Kotlin to virtual nodes","u":"internals.html#virtual-nodes","k":"How GuiLib works","s":"","b":"Tag functions like div , span , button or img are members of NodeBuilder . They don't create elements; they append a virtual node to the builder's list. A children lambda runs in a fresh builder whose list becomes the children of that node. +\"text\" appends a text node. Virtual node Created by Meaning VText +\"…\" , text(x) A text node. May contain § formatting codes. VElement div { } , button(…) , … An element: tag name, props (id, className, style string, attributes, event handlers, ref) and children. VComponent MyComponent(props) A component call: the component type, its props and an optional key. The component's function has not run yet. VProvider Ctx.Provider(value) { } Makes a context value available to the subtree. VPortal portal { } Children that are mounted into the overlay layer instead of in place. Virtual nodes are plain immutable objects and are rebuilt on every render. That is cheap (a few small allocations per node) and it means your render function can be ordinary Kotlin: if , for , when , helper functions ( fun NodeBuilder.row(…) ), early returns. Nothing is kept between renders except what hooks keep. The tag functions themselves are generated from one table ( scripts/gen_tags.py → Tags.kt ), which is why every tag has the same common parameters ( className , id , style , key , the event handlers) plus its own attributes ( src , value , colSpan , …)."},{"t":"Components and the reconciler","u":"internals.html#reconciler","k":"How GuiLib works","s":"","b":"A component ( component(\"Name\") { … } ) is a function from props to virtual nodes. GuiLib keeps a mounted instance for every virtual node it has rendered, forming a second tree next to the DOM: Instance Owns HostInstance One DOM Element and the instances of its children. TextInstance One DOM TextNode . ComponentInstance The hook list, a dirty flag, the instances of whatever the component rendered. No DOM node of its own: a component's output is spliced into its parent element. ProviderInstance A context value and the set of components that read it. PortalInstance A container element inside the overlay layer."},{"t":"Diffing children","u":"internals.html#diffing-children","k":"How GuiLib works","s":"","b":"When a parent renders again, its new list of virtual children is matched against its old instances ( reconcileChildren ): Each child gets a match key: its key if you gave one, otherwise its index in the list. An old instance with the same key and the same type (same tag, same component type, same context, both text, both portals) is reused and updated . Otherwise a new instance is mounted . Old instances that weren't reused are unmounted : their effect cleanups run, their DOM nodes are removed. Duplicate keys among siblings are reported once in the log and fall back to their index. This is why keys matter in lists: without them, removing the first row makes every following row reuse the instance (and the state, focus, scroll position, running animations) of the row that was before it. With key = item.id each row keeps its own instance wherever it moves."},{"t":"Updating","u":"internals.html#updating","k":"How GuiLib works","s":"","b":"Element : id, class list, inline style, attributes, handlers and ref are written to the existing element; only real changes mark it for restyling. Then its children are reconciled. Text : the text node's data is replaced if different. Component : it renders again only if its props are not equals to the previous props, or if it was marked dirty by its own state. Props that are data class es or immutable values therefore skip unchanged subtrees for free. Provider : if the value changed, every component that read it with useContext is scheduled to render. After a host's children are reconciled, syncDom collects the DOM nodes all child instances contribute (components and providers contribute their children's nodes, portals contribute nothing) and sets them as the element's children in one step."},{"t":"Errors","u":"internals.html#errors","k":"How GuiLib works","s":"","b":"If a component's function throws, the error and the first stack lines are logged and the component keeps its previous output . One broken component doesn't take the screen down."},{"t":"Hooks under the hood","u":"internals.html#hooks","k":"How GuiLib works","s":"","b":"A component instance has a plain list of hook objects. Each useX call takes the next slot by position: the first call on the first render creates the state cell, effect record, memo or ref; later renders get the same object back from the same slot. That's the whole trick, and it's why hooks must be called unconditionally and in the same order. GuiLib checks the slot type on every call and throws hook order changed in <Name> if a useState slot is suddenly asked for a useEffect ; more or fewer hooks than on the first render are logged as warnings. Hook Stored in its slot Behaviour useState a State cell Setting a value that is not equals to the current one marks the component dirty and schedules it. Setters are thread-safe : called from another thread they post the change to the UI thread. useEffect deps + effect + cleanup scope Scheduled when the deps changed (or once, without deps). Runs after the DOM is updated; the previous cleanup runs first. Timers created through the effect scope are cancelled with it. useMemo deps + value Recomputed only when deps change. useRef a Ref box Survives renders, changing it renders nothing. Element refs are filled by the reconciler. useContext a marker Reads the nearest provider above and subscribes the component to it. useInterval a ref + an effect An interval on the document's clock, using the latest callback. useAsync / useFuture state + effect Runs work on a daemon thread pool; results are posted back to the UI thread and ignored if the component unmounted or the keys changed meanwhile."},{"t":"Batching: when components actually render","u":"internals.html#batching","k":"How GuiLib works","s":"","b":"Setting state never renders immediately. The component is put into a set of dirty components, and the document flushes that set at fixed points: after input events, after timers and posted tasks, and before styles are computed for a frame. The flush: renders dirty components parents first (sorted by depth), so a child that its parent re-renders anyway renders only once; after each component render, re-syncs the DOM of its nearest host element or portal; then runs all pending effects; effects may set state again, which starts another round; gives up after 50 rounds with a warning (an effect that always sets new state would otherwise loop forever). So ten setState calls in one click handler cause one render, and a state change in a deeply nested component only re-runs that component and the children whose props changed."},{"t":"The DOM","u":"internals.html#dom","k":"How GuiLib works","s":"","b":"The live tree consists of Element s and TextNode s, with the API you'd expect from the browser: tagName , id , classList (add / remove / toggle / replace), inlineStyle and setStyleProperty , attributes, children , parent , querySelector(All) with full CSS selectors, getBoundingClientRect() , focus() , scrollTop / scrollLeft , addEventListener . Every node also carries its LayoutBox (the layout result) and, for elements, its computed and animated style. body is the root and always exactly the size of the viewport; :root matches it. The overlay layer div#guilib-overlay is always the last child of the body. Portals (menus, tooltips, modals, toasts, the select dropdown) render into containers inside it, so they paint above everything and are never clipped by scroll containers. Controls with internal children : an input or textarea builds its own children (text span, caret, selection, placeholder) like a shadow DOM. The reconciler leaves them alone; the control keeps them in sync with the value. They're styled through classes like .guilib-caret and input::placeholder . Generated boxes for ::before / ::after are real elements attached to their host but not part of children (so querySelector doesn't see them); layout and painting include them. Replaced content : img , item , entity and player-head elements get a content object from the backend with a natural size; the layout treats them like an image, the renderer draws them itself. When an element changes it marks itself: style dirty (its class, attributes, state or inline style changed), layout dirty (its children, text or replaced content changed) or both. Dirty flags propagate to the ancestors so the next frame can find the changed spots without walking the whole tree."},{"t":"CSS: from text to computed styles","u":"internals.html#css","k":"How GuiLib works","s":"","b":""},{"t":"Parsing","u":"internals.html#parsing","k":"How GuiLib works","s":"","b":"A stylesheet goes through a tokenizer that follows CSS Syntax Level 3 (identifiers, numbers with units, strings, hashes, functions, blocks) and a parser that builds rules. At-rules are handled while parsing: @media rules keep their query; they're checked at match time against the viewport (in GUI px), the GUI scale ( resolution ), hover/pointer and preference features. Nested @media works. @supports is evaluated once while parsing : a condition is true when GuiLib knows the property and can parse the value, so the rules inside are either kept or dropped. @keyframes and @font-face are collected separately (fonts are global and registered with the font manager when the stylesheet is set). Anything invalid is skipped with a warning naming file, line and column (and a \"did you mean\" for misspelled properties). An unknown selector drops only its rule, an invalid value only its declaration. Each declaration is parsed into a typed value right away when it contains no var() (lengths, colors, keyword enums, gradient layers, transform lists …). Shorthands ( margin , background , flex , grid-area , border , transition …) are expanded into their longhands. Sheets come in three origins: the user-agent sheet ua.css (GuiLib's defaults for every tag and built-in control), your author sheets in the order you pass them, and inline style strings."},{"t":"Matching selectors","u":"internals.html#matching-selectors","k":"How GuiLib works","s":"","b":"All rules are put into an index keyed by the subject (the rightmost compound) of each selector: by id if it has one, else by its first class, else by tag name, else into a small \"universal\" list. To find the rules for an element, GuiLib only looks at the buckets for its id, each of its classes, its tag and the universal list. With hundreds of rules, an element is usually tested against a handful. A candidate selector is then matched right to left like in browsers: the subject compound against the element, then each combinator walks outwards (parent for > , any ancestor for a space, previous sibling for + and ~ ). Pseudo-classes test state bits ( :hover , :active , :focus , :focus-visible , :checked , :disabled , :scrolling ) or structure ( :first-child , :nth-child(2n+1 of .x) …). ::before , ::after and ::placeholder rules live in separate indexes per pseudo-element, so they cost nothing for elements that don't need them."},{"t":"The cascade","u":"internals.html#the-cascade","k":"How GuiLib works","s":"","b":"The declarations of all matching rules are sorted exactly like the CSS cascade: Copy 1. origin and importance ua < author < inline < author !important < inline !important < ua !important 2. specificity (ids, classes/attributes/pseudo-classes, types) of the selector that matched 3. source order later wins Then the computed style is built: Custom properties ( --name ) are collected first; they inherit from the parent's. Declarations with var() are substituted with the custom properties visible on this element (with fallbacks, nesting and cycle detection) and only then parsed. A value that is invalid after substitution becomes unset , like in browsers. For each property the winning value is resolved: inherit / unset on inherited properties copy the parent's computed value, initial uses the property's default. font-size is resolved first ( em and % refer to the parent's font size), then color (so currentColor works everywhere), then everything else: lengths become pixels where possible, % and calc() with percentages stay symbolic until layout knows the reference size, vw / vh / rem use the document's viewport and root font size. The result is a ComputedStyle : an array with one typed value per property (125 longhand properties). Two computed styles can be compared cheaply, and GuiLib knows which properties affect layout. That decides what a style change costs: What changed Consequence nothing (same values) nothing paint-only properties ( color , background , opacity , transform , box-shadow , filter , border-radius , cursor …) repaint only anything else ( width , padding , display , font-size …) relayout of this element and its ancestors, then repaint"},{"t":"Restyling only what changed","u":"internals.html#restyle","k":"How GuiLib works","s":"","b":"Styles are recomputed for dirty elements only. What marks an element dirty is chosen from what the stylesheets actually use: A class, id, attribute or inline style change restyles the element and its subtree (descendant selectors like .open .item may now match). A state change ( :hover …) restyles just the element, unless some selector tests a state on an ancestor ( .card:hover .title ), then its subtree too. If any selector uses sibling combinators or :nth-child(… of S) , changes also restyle the siblings. Viewport size and GUI scale changes restyle everything ( vw , @media ). A restyled element whose style turned out identical stops there: its children are only restyled when its own style actually changed (they might inherit from it)."},{"t":"Transitions and animations","u":"internals.html#animations","k":"How GuiLib works","s":"","b":"The animator sits between the cascade and layout. An element keeps two styles: computed : the cascade's result, the target ; animatedStyle : the value it shows right now while transitions or animations run (layout and painting read this one). When a new computed style arrives, every property that changed and is listed in transition starts a transition from the currently displayed value (so reversing a hover mid-way continues smoothly instead of jumping). @keyframes animations start when their name appears; their keyframes are computed as full styles once, with the implicit 0 % / 100 % frames taken from the element's own style. Every frame, tick advances all running transitions and animations with their timing functions ( ease , cubic-bezier() , steps() …), honouring delay, iteration count, direction, fill mode and play state, and writes the interpolated values. Like the cascade, transitions win over animations. The animator then reports which properties changed: only paint-only ones means repaint, anything else means relayout of that element's path. Interpolation is per value type: colors per channel, lengths and calc() mixes, transform lists function by function, shadow and filter lists entry by entry, gradients stop by stop, visibility switches at the visible end. Values that can't be interpolated switch at the end. Details that make it feel right: a transition started during a frame is drawn at its start value in that same frame (no one-frame flash of the end value); a finished animation doesn't replay just because the element is restyled again (it replays when its name is removed and added); cancelling a transition by removing it from transition jumps cleanly to the new value."},{"t":"Layout","u":"internals.html#layout","k":"How GuiLib works","s":"","b":"Layout turns styles into boxes. It works on the LayoutNode interface (implemented by elements and text nodes, and by plain fakes in the tests) and writes a LayoutBox per node: position relative to the parent's border box, border-box size, margin / border / padding, baseline, scroll size and the laid-out lines of inline content. layoutNode(node, available space …) is the one entry point. It resolves margins, padding and border, decides the width (specified, stretched, shrink-to-fit or intrinsic), lays out the content with the formatting context the node's display asks for, decides the height, then places its absolutely positioned descendants and computes its scroll size. The caller positions the node itself."},{"t":"Formatting contexts","u":"internals.html#formatting-contexts","k":"How GuiLib works","s":"","b":"display Algorithm block Children stacked vertically with their margins (no margin collapsing, a deliberate difference). Runs of inline-level children between blocks become paragraphs. margin: auto centers. inline content Text nodes, display: inline elements and atomic boxes (inline-block, images, items) are flattened into items, split into unbreakable chunks (respecting white-space , word-break , overflow-wrap ), measured and packed into lines. The lines are stored on the block as a paragraph of positioned fragments (text runs, boxes, inline edges). text-align , vertical-align , line-height , line-clamp and text-overflow act here. flex CSS Flexbox Level 1: flex base sizes (measuring content when the basis is auto ), hypothetical sizes clamped by min/max (with min-width: auto ), line breaking for wrap , the iterative grow/shrink resolution with freezing, cross sizes, align-items / align-self / align-content , auto margins, justify-content , gap , order . grid Track lists with px % fr auto min-content max-content minmax() repeat(n | auto-fill | auto-fit) , template areas, explicit and auto placement (row or column flow, dense ), spans, track sizing for intrinsic and flexible tracks, alignment, gaps; auto-fit collapses empty tracks. table HTML table model: row groups (head first, foot last), implicit rows, slot placement with colspan / rowspan , automatic or fixed column widths from min/max-content, border-collapse , border-spacing , row heights and vertical-align in cells, captions. Text is measured through TextMeasurer (the backend's font manager): width of a string and font metrics in a given style. Widths are measured at the exact physical pixel size and snapped like the renderer will draw them, so what layout reserves is what gets drawn. Intrinsic sizes (min-content: the widest unbreakable piece; max-content: everything on one line) are computed on demand for shrink-to-fit boxes, flex bases, grid tracks and table columns, and cached per node. Positioning : relative offsets the box after flow layout. absolute and fixed boxes are taken out of the flow and registered with their containing block (the nearest positioned ancestor, or the viewport for fixed ); once that block knows its size, they are laid out against it, using their static position where no inset is given. Every positioned box later becomes its own paint layer."},{"t":"Incremental layout","u":"internals.html#incremental-layout","k":"How GuiLib works","s":"","b":"Laying out a whole screen every frame would be wasteful when one element animates. GuiLib only lays out what changed: A change marks the node and all its ancestors dirty (an ancestor's size can depend on its children). Each node remembers the result of its last layouts together with their inputs : available width and height, the sizing mode, sizes forced by a flex or grid parent, the table cell shift. When a parent lays out a clean child with inputs it has seen before, the child's stored size is restored and its whole subtree is skipped ; only its position is set again. Flex items are measured and then laid out with other inputs in every pass, so a node keeps several results. If a pass ends with a subtree laid out for different inputs than its final ones, it is fixed up at the end of the pass. A node with absolutely positioned descendants whose containing block is outside it is never reused (those boxes depend on more than the node's inputs). Changes outside the tree (fonts, viewport, GUI scale) throw all stored results away. The effect: an animated element in a list of 60 rows lays out 4 nodes per frame instead of 124. Every unit test runs with a verification mode that lays out everything again after each incremental pass and fails on any difference; in game you can turn it on with -Dguilib.layout.verify=log ."},{"t":"Painting: the display list","u":"internals.html#painting","k":"How GuiLib works","s":"","b":"The painter walks the laid-out tree and emits drawing commands in back-to-front order, plus a hit region for every element that can receive the mouse. It never talks to Minecraft; the commands are plain data: Command Draws Box A rectangle with background color, four border widths and colors and four corner radii. Shadow A box-shadow (outer or inset, blurred, spread, offset), or a blurred shape for filter . Gradient Any gradient (linear, radial, conic, repeating) as a mesh of colored triangles, clipped to the box and its rounded corners. Meshes are cached and reused when only the position changes. Text One run of text in one style and color at a position ( § codes were already split into runs). Image An image source fitted into a rectangle, with SVG currentColor and CSS filter operations. Replaced An element the backend draws itself: item, entity, player head. PushClip / PopClip Rectangular clipping for overflow (rounded parent corners clip their corner children). SetTransform A matrix for the following commands (rotated, skewed or mirrored elements)."},{"t":"Order, opacity, transforms, clips","u":"internals.html#order-opacity-transforms-clips","k":"How GuiLib works","s":"","b":"Stacking : an element paints its decorations (shadows, background, border, inset shadows), its inline content, its in-flow children; positioned descendants are collected as layers and painted after, sorted by z-index and then document order. Each positioned element is its own layer (simplified CSS stacking contexts). opacity multiplies into every color of the subtree; nothing is rendered offscreen. transform : layout positions never include transforms. Axis-aligned transforms (translate, positive scale) are folded into the coordinates of every emitted command, so boxes stay pixel-exact and scaled text is rasterized sharp at its new size. Rotation, skew and mirroring emit a SetTransform and the commands stay in layout coordinates. Clips are pushed for overflow other than visible , in screen coordinates. Positioned layers that paint later re-push the clips of the containers they belong to, so they can't escape a scroll container. filter rewrites the commands an element emitted (colors through a color matrix, boxes into blurred shadows, images through pixel operations, a shadow copy inserted underneath for drop-shadow ). Hit regions are recorded in paint order with their clip and transform. Hit testing walks them from the last (topmost) to the first and returns the first element whose region contains the point, so what you see on top is what you click. pointer-events: none simply doesn't record a region."},{"t":"Drawing in Minecraft","u":"internals.html#drawing","k":"How GuiLib works","s":"","b":"The command renderer converts the display list into Minecraft's GUI render states each frame. Minecraft collects those states, batches them by pipeline and texture, and draws them with its normal GUI pass, so GuiLib composes correctly with vanilla tooltips, items and other mods' overlays. Plain boxes (no radius) become vanilla colored rectangles: background plus up to four border strips. Rounded boxes and borders use GuiLib's own pipeline with a signed-distance-field fragment shader: the quad carries its size, four corner radii and border width, the shader computes the exact coverage per pixel. That's why corners are smooth at every scale. Shadows use a second shader that evaluates a Gaussian-blurred rounded rectangle analytically (no blur pass, no textures). Gradients are drawn as their triangle meshes with per-vertex colors. Text is drawn from glyph textures (see below) as one batched run per text command; the glyph quads of a run are cached and only rebuilt when the text, font or pixel size changes. Images are textured quads; SVGs and filtered images come from GuiLib's texture caches. Items, entities and player heads are drawn with Minecraft's own renderers, mapped through the current transform. Clips become Minecraft's scissor stack, transforms its pose matrix. Paint order : Minecraft sorts states within a layer for batching, which could change the order of overlapping elements. GuiLib adds its states directly to the current layer, tracks the screen areas it has drawn and moves to a new layer only when a new element overlaps an earlier one with a different batch key or after something Minecraft placed itself. This keeps the CSS order exact while big static screens still batch into a few draw calls. The shaders are written for the vanilla GUI vertex formats and work with every graphics backend Minecraft offers; for 26.3 a generated copy with explicit locations is compiled to SPIR-V."},{"t":"Text and fonts","u":"internals.html#fonts","k":"How GuiLib works","s":"","b":"Fonts are TrueType/OpenType files loaded with FreeType , the same library Minecraft uses. Built in: Inter (default, bundled) and minecraft (the vanilla font). More come from @font-face or FontManager.register ; font-family , font-weight (also variable fonts) and font-style pick the face. Glyphs are rendered at the exact physical pixel size : font-size × GUI scale (× the scale of axis-aligned transforms). There is no scaling of a texture, which is why text is sharp at every GUI scale. Rendered glyphs are packed into 1024 × 1024 atlas pages (white pixels with coverage as alpha, so one texture works for every color). A glyph is rendered once per font, size and character. Rotated or skewed text is rasterized at twice the size and sampled with filtering, so it stays smooth. Characters a font doesn't have fall back to Minecraft's font (CJK, emoji …). § color and format codes are split into styled runs before layout ever sees the text; text(component) turns Minecraft Component s into spans with their colors, styles, hover and click events. letter-spacing is added by a measuring wrapper around the font manager, so layout and drawing agree."},{"t":"Images","u":"internals.html#images","k":"How GuiLib works","s":"","b":"img(src) and background-image: url() take resource locations ( modid:path/file.png ). The natural size is known when the element is created, so layout never waits for an image. PNG goes through Minecraft's texture manager. SVG is parsed with JSVG and rasterized at the exact on-screen pixel size, cached per size and GUI scale (and per color when it uses currentColor ). The SVG engine is warmed up on a background thread at startup so the first SVG doesn't stutter. GIF frames are decoded and composited on a background thread; the element shows nothing until they're ready, then plays on its own clock with the right frame delays and loop count. filter on images produces filtered textures (color matrix, blur, silhouette for drop shadows), cached."},{"t":"Input and events","u":"internals.html#events","k":"How GuiLib works","s":"","b":"GuiLibScreen receives Minecraft's mouse, wheel, key and character callbacks, converts positions into the document's coordinates and hands them to the InteractionController , which keeps the interaction state and turns raw input into DOM events: Mouse move : hit test → the hovered element and its ancestor chain. Elements that entered or left the chain get :hover set or cleared and receive mouseenter / mouseleave ; the target gets mousemove . After every layout the hover is refreshed, so content moving under a still mouse updates :hover too. Mouse down : mousedown on the target, :active on its chain, focus moves to the nearest focusable ancestor (unless the event was cancelled), then default actions run (an input places its caret, a select opens …). Mouse up : mouseup , and click (with click count for dblclick ) if released on the element that was pressed. mousemove / mouseup also reach document listeners when the mouse is outside every element, which is what drags rely on. Wheel : wheel event; if not cancelled, the nearest scroll container under the mouse that can still scroll in that direction scrolls (Shift for sideways). Keys : keydown / keyup / char go to the focused element (or the body). Default actions: Tab / Shift+Tab move focus, Enter / Space activate buttons, the controls handle editing keys, Escape closes the screen if nothing used it. Labels forward clicks to their control; disabled elements swallow input. Dispatch follows the DOM: a capture phase from the body down to the target's parent (handlers registered with capture ), the target, then bubbling back up for events that bubble. stopPropagation() ends the walk, preventDefault() skips GuiLib's default action. Events are processed immediately; the state changes they cause are flushed right after each event."},{"t":"One frame, step by step","u":"internals.html#frame","k":"How GuiLib works","s":"","b":"Each time Minecraft renders the screen, GuiLibScreen runs UiRoot.frame(width, height) and draws the result. Inside: Copy Document.update 1. run tasks posted from other threads (state set off-thread, async results) 2. run due timers (setTimeout / setInterval / useInterval) 3. flush: render dirty components (parents first), run effects, repeat until settled 4. viewport size or GUI scale changed? → restyle everything, drop all layout results 5. styles for dirty elements (+ animator notices new transitions / animations) 6. layout for dirty paths (incremental) 7. animator.tick: write this frame's in-between values → mark changed elements 8. frame hooks (inputs position their caret and selection from the layout) 9. styles + layout again for whatever 7 and 8 changed 10. transitions started in 9 get their start values now Painter (only if something visible changed) 11. build the display list and hit regions 12. refresh hover (content may have moved under the mouse); if that changed styles, settle once more CommandRenderer 13. convert the display list into Minecraft render states If nothing changed, steps 3–12 do no work and step 13 draws the previous display list. The metrics overlay (Ctrl + F12) shows how long each phase takes."},{"t":"Coordinates and scaling","u":"internals.html#scaling","k":"How GuiLib works","s":"","b":"CSS px are GUI pixels : Minecraft's scaled coordinates. At GUI scale 2 one CSS px is two physical pixels. The viewport is the screen in GUI pixels; vw , vh and @media (width) use it, @media (resolution) is the GUI scale. With an own scale ( useScreenScale(2.5f) , GuiLib.open(scale = …) ) the document gets a viewport of window size ÷ scale and is drawn under an extra pose scale; mouse positions are divided by the same factor and text and SVGs are rasterized for the new pixel size, so it stays sharp at fractional scales. Layout positions are fractional; plain boxes and their borders are snapped to the pixel grid when drawn, rounded boxes are anti-aliased by their shader."},{"t":"Threads","u":"internals.html#threads","k":"How GuiLib works","s":"","b":"Everything that touches the tree runs on Minecraft's render thread (the document's UI thread). State setters are safe from any thread: off-thread calls are queued and applied at the start of the next frame. document.post { } and GuiLib.runOnUi { } do the same for arbitrary code. useAsync / useFuture / usePromise run work on a daemon thread pool and post results back. Background threads of GuiLib itself: GIF decoding, the SVG warm-up at startup and the metrics overlay's JVM queries. None of them touch the tree. The system clipboard is accessed on the render thread ( useClipboard )."},{"t":"What costs what","u":"internals.html#performance","k":"How GuiLib works","s":"","b":"Situation Work per frame Nothing changes Posted tasks and timers are checked, the previous display list is drawn. No styles, layout or painting. Mouse moves over static content Hit test; on a hover change: restyle of the affected elements, repaint (and relayout only if :hover rules change layout properties). A paint-only animation ( opacity , transform , colors) Animator tick + repaint. No layout. A layout animation ( height , width , …) Animator tick + layout of the animated element's path (siblings and other subtrees are reused) + repaint. State change in one component That component renders, its DOM is patched, changed elements restyle, changed paths lay out, repaint. Typing in an input The input's internal text node changes → its line relayouts, caret moves, repaint. Window resize / GUI scale change Everything is restyled and laid out once. Memory: virtual nodes are short-lived; the DOM, computed styles and layout boxes live as long as their elements. Caches are bounded: glyph atlas pages, SVG rasters, gradient meshes, glyph runs, image filters, player profiles. Closing a screen unmounts everything (effects clean up, timers stop); the caches stay so the next screen opens quickly. Measured on the showcase (26.2, warmed up): a static page costs about 0.05–0.1 ms of GuiLib time per frame (almost all of it drawing), the animation page about 0.2 ms (styles 0.02, layout 0.07, display list 0.06, drawing 0.03). One frame at 60 FPS has 16.7 ms."},{"t":"Built-in controls","u":"internals.html#controls","k":"How GuiLib works","s":"","b":"Every control ( select , slider , tabs , modal , sortableList , colorPicker , toasts …) is built from the same public pieces you use: components, hooks, plain elements with guilib-* classes, portals for anything that floats, and rules in ua.css that use --guilib-* theme variables. That's why you can restyle every part with ordinary CSS and why they follow accent-color and your theme. Two controls need engine support: input and textarea manage their own child elements (text, caret, selection, placeholder), handle editing keys, the clipboard and IME text input, and position the caret from the layout in a frame hook. Popups (select menus, tooltips, the color popover) measure their anchor after layout and flip or shift to stay on screen."},{"t":"Development tools","u":"internals.html#dev-tools","k":"How GuiLib works","s":"","b":"CSS hot reload (dev environment or -Dguilib.hotReload=true ): for every stylesheet in use, its source file under src/main/resources is found and polled twice a second; on a change all open GuiLib screens reload their CSS without losing state. /guilib reload does it manually. Warnings with file, line and column for CSS problems, and for hook misuse, duplicate keys and render errors (each logged once). Metrics overlay (Ctrl + F12, draggable by its title bar): frame time per phase, work per second, CPU, memory, GC, leak check. It is a separate document and leaves itself out of its numbers. Layout verification -Dguilib.layout.verify=log : compares every incremental layout with a full one and logs differences. Showcase ( /guilib showcase ): every feature on one screen."},{"t":"Source map","u":"internals.html#source-map","k":"How GuiLib works","s":"","b":"Where to find things in the repository ( src/main/kotlin/net/sbo/guilib/ ): Path Responsibility core/dsl/Builder.kt NodeBuilder , ComponentScope , all hooks, State . core/dsl/Tags.kt Generated tag functions (edit scripts/gen_tags.py ). core/dsl/Controls.kt , Widgets.kt , Async.kt Public control functions, widget hooks, async hooks. core/dom/VNode.kt Virtual node types, component() , contexts, refs. core/dom/Reconciler.kt Mount / update / unmount, child diffing, effects. core/dom/Node.kt Element , TextNode , class lists, attributes, dirty flags, pseudo boxes. core/dom/Document.kt The frame update, batching, timers, focus, portals, restyle walk. core/css/Tokenizer.kt , Parser.kt CSS syntax, rules, at-rules. core/css/Selector.kt Selector parsing, matching, specificity. core/css/Properties.kt , Values.kt Every property: name, inheritance, initial value, value parser; shorthands. core/css/StyleEngine.kt , ComputedStyle.kt Rule index, cascade, var() , computed values. core/css/Media.kt , Supports.kt , FontFace.kt , Animation.kt , Transform.kt , Filter.kt , Background.kt , Grid.kt , Calc.kt The parsers and models of the respective features. core/anim/ Animator (transitions, keyframes) and interpolation. core/layout/LayoutEngine.kt Box model, block flow, flexbox, positioning, intrinsic sizes, incremental layout. core/layout/InlineLayout.kt , GridLayout.kt , TableLayout.kt Inline formatting, grid, tables. core/paint/Painter.kt , DisplayList.kt Display list, stacking, clips, transforms, hit regions. core/paint/GradientMesh.kt , Filters.kt , BackgroundTiles.kt , BorderDashes.kt Gradient meshes, filter rewriting, background tiling, dashed borders. core/event/ Event types, dispatcher, interaction controller. core/controls/ Built-in controls and their internals. fabric/GuiLibScreen.kt , GuiLib.kt The Minecraft screen, the public entry points. fabric/render/ Command renderer, pipelines and render states. fabric/font/ , fabric/image/ FreeType fonts, glyph atlas, images. fabric/input/ , fabric/entity/ , fabric/resources/ , fabric/debug/ Keys and cursors, entity rendering, stylesheet loading and hot reload, metrics overlay. src/main/resources/assets/guilib/css/ua.css Default styles of every tag and control, theme variables. src/main/resources/assets/guilib/shaders/ Rounded rectangle and box shadow shaders."},{"t":"Elements","u":"elements.html","k":"page","s":"Tag functions build elements with HTML names. Every tag takes the same common props and event handlers; children go in the trailing lambda.","b":"Tag functions build elements with HTML names. Every tag takes the same common props and event handlers; children go in the trailing lambda."},{"t":"Common props","u":"elements.html#common-props","k":"Elements","s":"","b":"Prop Type Description className String? CSS classes separated by spaces , like HTML class : className = \"btn primary big\" . Not commas (see Classes ). id String? Element id for #id selectors and querySelector . style String? Inline CSS as a string : style = \"width: 20px; color: red\" . key Any? Identity among siblings (lists). title String? Native tooltip shown after hovering for 500 ms. ref Ref<Element?>? Receives the Element (see useElementRef ). tabIndex Int? Makes the element focusable ( 0 : in Tab order, -1 : only by click/code). Events lambdas onClick , onDoubleClick , onContextMenu , onMouseDown , onMouseUp , onMouseMove , onMouseEnter , onMouseLeave ( MouseEvent ), onWheel ( WheelEvent ), onKeyDown , onKeyUp ( KeyboardEvent ), onFocus , onBlur ( FocusEvent ), onScroll ( ScrollEvent ). See Events . Copy div(className = \"card\", id = \"main\", style = \"padding: 4px\", title = \"A card\", onClick = { e -> println(e.clientX) }) { +\"children go here\" }"},{"t":"Structure & text","u":"elements.html#structure-text","k":"Elements","s":"","b":"Tags Default display Notes div section header footer nav main aside article form block Generic containers. p h1 h2 h3 h4 block Small bottom margins; headings are bold (2em, 1.5em, 1.25em, 1em). ul ol li block Lists (no bullets by default). pre block white-space: pre and the Minecraft font. hr block Thin divider line. span a strong b em i small sub sup code label inline b / strong bold, em / i italic, small 0.85em, sub / sup subscript/superscript (0.75em, shifted), code Minecraft font. label forwards clicks to the first input/select/button inside. br – Line break inside text. text(component) inline A Minecraft Component (chat message, item name, Component.translatable ): colors incl. RGB, bold/italic/underline/strikethrough, show_text hover events as tooltips, show_item hover events as Minecraft's item tooltip ( text(stack.displayName) = an item link like in chat), click events (links, commands, copy) like in chat. span.guilib-text , clickable parts .guilib-text-link . button inline-flex Centered content, disabled . Enter/Space activate a focused button. Disabled elements get no mouse events."},{"t":"Tables","u":"elements.html#tables","k":"Elements","s":"","b":"Real HTML tables: table caption colgroup col thead tbody tfoot tr th td . Columns line up across rows, and the table is as wide as its content (or fills a width ). Column widths work like in a browser: each column fits its widest cell, a px width on a cell fixes its column, a % asks for that share of the table, and extra width goes to the auto columns. td / th take colSpan and rowSpan ( 0 = to the end of the group). thead is always drawn first and tfoot last. Rows and row groups have their own boxes, so tr:hover , tr:nth-child(even) and onClick on a tr work. Defaults: border-spacing: 1px , cell padding 1px, cells vertically centered, th bold and centered. Table CSS: border-collapse, border-spacing, table-layout, caption-side . Copy table(className = \"party\") { caption { +\"Party\" } thead { tr { th { +\"Player\" }; th { +\"Class\" }; th(className = \"num\") { +\"Level\" } } } tbody { for (m in members) tr(key = m.name, className = classNames(\"selected\" to (m.name == selected)), onClick = { selected = m.name }) { td { +m.name }; td { +m.clazz }; td(className = \"num\") { +m.level.toString() } } } tfoot { tr { td(colSpan = 2) { +\"Average\" }; td(className = \"num\") { +avg } } } } Copy .party { width: 100%; border-spacing: 0; border: 1px solid #3f4147; } .party th, .party td { padding: 3px 6px; text-align: left; } .party .num { text-align: right; } .party tbody tr:nth-child(even) { background-color: #ffffff08; } .party tbody tr:hover { background-color: #ffffff14; } /* Grid lines drawn once between cells: */ .grid { border-collapse: collapse; } .grid td, .grid th { border: 1px solid #3f4147; } Tables: header, zebra rows, hover and selection, colspan/rowspan with collapsed borders A tr or td without its wrapper gets an implicit one (without a box). Not supported: col backgrounds, visibility: collapse , empty-cells ; a rowspan cell is painted before the later rows it covers, so a background on those rows hides its lower part."},{"t":"GuiLib tags","u":"elements.html#guilib-tags","k":"Elements","s":"","b":""},{"t":"scroll","u":"elements.html#scroll","k":"GuiLib tag","s":"A block element with overflow: auto and a thin scrollbar. Any element with overflow: auto/scroll scrolls as well; scroll is a convenient def","c":"","b":"# scroll GuiLib tag A block element with overflow: auto and a thin scrollbar. Any element with overflow: auto/scroll scrolls as well; scroll is a convenient default. Copy fun NodeBuilder.scroll(className: String? = null, …, children: NodeBuilder.() -> Unit) Example Copy scroll(className = \"list\", style = \"max-height: 120px\") { for (p in parties) PartyRow(p, key = p.id) } Scroll containers, horizontal scrolling and scrollbar styling"},{"t":"img","u":"elements.html#img","k":"tag","s":"An image from your resources (PNG, SVG or GIF). Its natural size is the image size; object-fit is supported. Animated GIFs (since 0.3.1) loo","c":"","b":"# img tag An image from your resources (PNG, SVG or GIF). Its natural size is the image size; object-fit is supported. Animated GIFs (since 0.3.1) loop like in a browser; all images with the same src play in sync. GIFs are decoded in the background: a big one stays empty for a moment instead of freezing the game. currentColor inside an SVG is the element's CSS color , so one icon file can be tinted from CSS (see below). Copy fun NodeBuilder.img( src: String, alt: String? = null, className: String? = null, id: String? = null, style: String? = null, key: Any? = null, ) Parameter Type Default Description src String required Resource location, e.g. \"mymod:textures/gui/logo.png\" . alt String? null Alternative text. className , id , style , key Standard props (see Elements ). Example Copy img(\"mymod:textures/gui/logo.svg\", className = \"logo\", style = \"width: 32px; height: 32px\") PNG, SVG and animated GIF images with object-fit"},{"t":"Tinting SVG icons","u":"elements.html#svg-current-color","k":"Elements","s":"","b":"Draw the icon with currentColor and set the color in CSS. The icon follows color like text does: inherited from its button, on :hover , in themes. One file is enough for light and dark UIs. SVG Copy <!-- assets/mymod/icons/refresh.svg --> <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"> <path d=\"M20 12a8 8 0 1 1-2.34-5.66\"/><path d=\"M20 4v5h-5\"/> </svg> Kotlin Copy button(className = \"refresh\") { img(\"mymod:icons/refresh.svg\"); +\"Refresh\" } Copy .refresh img { width: 9px; height: 9px; } .refresh:hover { color: var(--guilib-accent); } /* text and icon turn blue together */ .light-theme .refresh { color: #1f2328; } /* the same file on a light background */ One refresh.svg in six colors, the light button hovered (Showcase → Images) Browsers don't pass color into <img> SVGs (only into inline SVG); GuiLib does, for img and background-image: url(…) . Parts with a fixed color stay as they are, and a color attribute on the root <svg> wins. Each color is rasterized once and cached, so animating color on a big SVG costs a re-rasterization per frame."},{"t":"item","u":"elements.html#item","k":"GuiLib tag","s":"Renders a Minecraft item stack like in an inventory slot (16×16 by default; size it with CSS). Needs a loaded world.","c":"","b":"# item GuiLib tag Renders a Minecraft item stack like in an inventory slot (16×16 by default; size it with CSS). Needs a loaded world. Copy fun NodeBuilder.item( stack: ItemStack, decorations: Boolean = true, tooltip: Boolean = false, className: String? = null, id: String? = null, style: String? = null, key: Any? = null, ) Parameter Type Default Description stack ItemStack required The item stack (typed Any so the core stays Minecraft-free). decorations Boolean true Show count and durability bar. tooltip Boolean false Show Minecraft's item tooltip (name, lore, enchantments …) while the icon is hovered, like in an inventory. className , id , style , key Standard props (see Elements ). Example Copy item(ItemStack(Items.DIAMOND_SWORD), tooltip = true, style = \"width: 32px; height: 32px\") Item icons at different sizes, with decorations"},{"t":"entity","u":"elements.html#entity","k":"GuiLib tag","s":"Renders a living entity scaled to fit its box, like the inventory player model (48×72 by default). Scrolling, clipping, scale() and useScree","c":"","b":"# entity GuiLib tag Renders a living entity scaled to fit its box, like the inventory player model (48×72 by default). Scrolling, clipping, scale() and useScreenScale work; inside rotate() / skew() the model stays upright. Copy fun NodeBuilder.entity( entity: LivingEntity, followMouse: Boolean = false, lookX: Float = 0f, lookY: Float = 0f, scale: Float = 1f, className: String? = null, id: String? = null, style: String? = null, key: Any? = null, ) Parameter Type Default Description entity LivingEntity required The entity, e.g. a FakePlayer . followMouse Boolean false Look at the mouse cursor. lookX Float 0f Look offset in px when not following the mouse. lookY Float 0f Look offset in px when not following the mouse. scale Float 1f Extra scale on top of fitting the box. className , id , style , key Standard props (see Elements ). Example Copy val me = useMemo { FakePlayer.ofLocalPlayer() } // create once; null without a world val notch = useMemo { FakePlayer.of(\"Notch\") } div(className = \"models\") { me?.let { entity(it, followMouse = true) } notch?.let { entity(it, lookX = -20f) } } Player models: the local player following the mouse, and a player by name"},{"t":"FakePlayer","u":"elements.html#fakeplayer","k":"class","s":"Client-side player entities for entity(...) (package net.sbo.guilib.fabric.entity ). Every factory returns null when no world is loaded, so ","c":"","b":"# FakePlayer class Client-side player entities for entity(...) (package net.sbo.guilib.fabric.entity ). Every factory returns null when no world is loaded, so create them once with useMemo . Skins are resolved asynchronously. Copy FakePlayer.ofLocalPlayer(): FakePlayer? FakePlayer.of(name: String): FakePlayer? FakePlayer.of(uuid: UUID): FakePlayer? FakePlayer.of(profile: GameProfile): FakePlayer? FakePlayer.of(player: AbstractClientPlayer): FakePlayer?"},{"t":"playerHead","u":"elements.html#playerhead","k":"GuiLib tag","s":"A player's face like in the tab list (16×16 by default), scaled to its box. The skin loads in the background (the default skin is shown unti","c":"","b":"# playerHead GuiLib tag A player's face like in the tab list (16×16 by default), scaled to its box. The skin loads in the background (the default skin is shown until then); no world is needed. The CSS tag selector is player-head . Copy fun NodeBuilder.playerHead( player: Any, hat: Boolean = true, className: String? = null, id: String? = null, style: String? = null, key: Any? = null, ) Parameter Type Default Description player Any required A name ( String ), UUID , GameProfile , ResolvableProfile or AbstractClientPlayer . hat Boolean true Draw the hat layer. className , id , style , key Standard props (see Elements ). Example Copy for (member in party) div(className = \"member\") { playerHead(member.name, style = \"margin-right: 4px\") +member.name } playerHead(uuid, style = \"width: 32px; height: 32px\")"},{"t":"Structure helpers","u":"elements.html#structure-helpers","k":"Elements","s":"","b":""},{"t":"fragment","u":"elements.html#fragment","k":"function","s":"Groups children without a wrapper element (like <>…</> ), e.g. to give a group of elements a key.","c":"","b":"# fragment function Groups children without a wrapper element (like <>…</> ), e.g. to give a group of elements a key. Copy fun NodeBuilder.fragment(key: Any? = null, children: NodeBuilder.() -> Unit)"},{"t":"portal","u":"elements.html#portal","k":"function","s":"Renders children into the overlay layer above everything else (like createPortal(children, document.body) ). Position the content with posit","c":"","b":"# portal function Renders children into the overlay layer above everything else (like createPortal(children, document.body) ). Position the content with position: fixed . Menus, tooltips and modals use portals so they are never clipped by scroll containers. Copy fun NodeBuilder.portal(className: String? = null, key: Any? = null, children: NodeBuilder.() -> Unit) Example Copy portal { div(className = \"popover\", style = \"position: fixed; left: ${x}px; top: ${y}px\") { +\"Above everything\" } }"},{"t":"Fonts","u":"elements.html#fonts","k":"Elements","s":"","b":"font-family accepts inter (default, bundled), minecraft (the vanilla font; alias monospace ) and your own TTF/OTF fonts, declared with @font-face in a stylesheet or registered in code. src takes resource locations (the first one that exists is used; local() and web URLs are not supported). Weights map to the nearest face (400/500/600/700); a range like font-weight: 100 900 covers every weight (variable fonts are drawn at their default instance). Fonts are global: a family declared once works in every screen. Copy @font-face { font-family: \"Roboto\"; src: url(\"mymod:fonts/roboto-regular.ttf\") format(\"truetype\"); } @font-face { font-family: \"Roboto\"; src: url(\"mymod:fonts/roboto-bold.ttf\"); font-weight: bold; } .title { font-family: \"Roboto\", inter; } Copy // The same in code: FontManager.register(\"roboto\", 400, false, \"mymod:fonts/roboto-regular.ttf\") FontManager.register(\"roboto\", 700, false, \"mymod:fonts/roboto-bold.ttf\") Text: weights, sizes, wrapping, ellipsis, § codes and the Minecraft font"},{"t":"Form controls","u":"controls.html","k":"page","s":"Ready-made, styleable controls. All of them are controlled like React: pass the current value, update your state in onChange .","b":"Ready-made, styleable controls. All of them are controlled like React: pass the current value, update your state in onChange . Controlled components: input(value = name, onChange = { name = it.value }) . The control shows exactly what you pass; onChange fires on every edit (React semantics, not the DOM change event). Every control is built from plain elements with guilib-* classes, so you can restyle it in your own CSS. The accent color comes from --guilib-accent . Text inputs, select, checkbox, switches and sliders"},{"t":"Text","u":"controls.html#text","k":"Form controls","s":"","b":""},{"t":"input","u":"controls.html#input","k":"tag","s":"Single-line text field ( text , password , number ) or checkbox. Supports a blinking caret, mouse and Shift+arrow selection, double-click wo","c":"input .guilib-input-text .guilib-placeholder .guilib-caret .guilib-selection","b":"# input tag Single-line text field ( text , password , number ) or checkbox. Supports a blinking caret, mouse and Shift+arrow selection, double-click word selection and Ctrl/Cmd+A/C/X/V with the system clipboard. Typed § is shown literally. text-align: center / right aligns the text, placeholder and caret. Copy fun NodeBuilder.input( type: String = \"text\", value: String? = null, placeholder: String? = null, checked: Boolean = false, disabled: Boolean = false, maxLength: Int? = null, autoFocus: Boolean = false, onChange: ((InputEvent) -> Unit)? = null, onInput: ((InputEvent) -> Unit)? = null, className: String? = null, id: String? = null, style: String? = null, key: Any? = null, ) Parameter Type Default Description type String \"text\" \"text\" , \"password\" , \"number\" (filters to digits, - , . , , ) or \"checkbox\" . value String? null Controlled text. Without it the input keeps its own text. placeholder String? null Shown while empty. checked Boolean false For checkboxes. disabled Boolean false Greyed out, not focusable. maxLength Int? null Maximum length (never cuts an emoji in half). autoFocus Boolean false Focus when it appears. onChange ((InputEvent) -> Unit)? null Every edit; it.value , it.checked . onInput ((InputEvent) -> Unit)? null Same as onChange . className , id , style , key Standard props (see Elements ). Keyboard Arrows, Ctrl+arrows (words), Home/End, Backspace/Delete (Ctrl: words), Ctrl+A/C/X/V, first Escape blurs Example Copy input(value = name, onChange = { name = it.value }, placeholder = \"Your IGN\", maxLength = 16) CSS input .guilib-input-text .guilib-placeholder .guilib-caret .guilib-selection"},{"t":"textarea","u":"controls.html#textarea","k":"function","s":"Multi-line text field with word wrap. Enter inserts a line break; it scrolls vertically when the text is taller than rows lines. text-align:","c":"textarea .guilib-textarea-line .guilib-placeholder .guilib-caret .guilib-selection","b":"# textarea function Multi-line text field with word wrap. Enter inserts a line break; it scrolls vertically when the text is taller than rows lines. text-align: center / right aligns every line. Copy fun NodeBuilder.textarea( value: String? = null, onChange: ((InputEvent) -> Unit)? = null, placeholder: String? = null, rows: Int = 3, maxLength: Int? = null, maxLines: Int? = null, disabled: Boolean = false, autoFocus: Boolean = false, ref: Ref<Element?>? = null, onInput, onKeyDown, onFocus, onBlur: … = null, className: String? = null, id: String? = null, style: String? = null, key: Any? = null, ) Parameter Type Default Description value String? null Controlled text (with \\n line breaks). onChange ((InputEvent) -> Unit)? null Every edit; it.value . placeholder String? null Shown while empty. rows Int 3 Visible lines: without a CSS height the field is exactly this many lines tall plus padding and border; more text scrolls. maxLength Int? null Maximum length. maxLines Int? null Maximum number of lines: Enter does nothing at the limit, extra line breaks in pasted text become spaces. Wrapped lines don't count. disabled Boolean false autoFocus Boolean false ref Ref<Element?>? null onInput, onKeyDown, onFocus, onBlur … null Like on input . className , id , style , key Standard props (see Elements ). Keyboard Arrows (Up/Down keep the column), Home/End (line; Ctrl: whole text), PageUp/PageDown, Enter, Ctrl+A/C/X/V Example Copy var note by useState(\"\") textarea(value = note, onChange = { note = it.value }, placeholder = \"Describe your party…\", rows = 4, maxLength = 256, maxLines = 4) span(className = \"muted\") { +\"${note.length}/256\" } CSS textarea .guilib-textarea-line .guilib-placeholder .guilib-caret .guilib-selection A textarea with two lines (and toasts in the corner)"},{"t":"Toggles","u":"controls.html#toggles","k":"Form controls","s":"","b":""},{"t":"checkbox","u":"controls.html#checkbox","k":"function","s":"A label with an input(type = \"checkbox\") and optional text. Clicking the text toggles too.","c":"input[type=checkbox] .guilib-check .guilib-checkbox","b":"# checkbox function A label with an input(type = \"checkbox\") and optional text. Clicking the text toggles too. Copy fun NodeBuilder.checkbox( checked: Boolean, onChange: ((InputEvent) -> Unit)? = null, label: String? = null, disabled: Boolean = false, className: String? = null, key: Any? = null, ) Parameter Type Default Description checked Boolean required Current state. onChange ((InputEvent) -> Unit)? null it.checked is the new state. label String? null Text next to the box. disabled Boolean false className , key Standard props (see Elements ). Example Copy checkbox(checked = agree, onChange = { agree = it.checked }, label = \"Show me in the party finder\") CSS input[type=checkbox] .guilib-check .guilib-checkbox"},{"t":"switch","u":"controls.html#switch","k":"function","s":"An animated on/off switch (sliding pill). Same onChange as checkbox .","c":".guilib-switch .checked .guilib-switch-track .guilib-switch-thumb .guilib-switch-label","b":"# switch function An animated on/off switch (sliding pill). Same onChange as checkbox . Copy fun NodeBuilder.switch( checked: Boolean, onChange: ((InputEvent) -> Unit)? = null, label: String? = null, disabled: Boolean = false, className: String? = null, id: String? = null, key: Any? = null, ) Parameter Type Default Description checked Boolean required Current state. onChange ((InputEvent) -> Unit)? null it.checked is the new state. label String? null Text after the switch. disabled Boolean false className , id , key Standard props (see Elements ). Keyboard Space / Enter toggle a focused switch Example Copy var sounds by useState(true) switch(checked = sounds, onChange = { sounds = it.checked }, label = \"Sounds\") CSS .guilib-switch .checked .guilib-switch-track .guilib-switch-thumb .guilib-switch-label"},{"t":"Sliders & numbers","u":"controls.html#sliders-numbers","k":"Form controls","s":"","b":""},{"t":"slider","u":"controls.html#slider","k":"function","s":"A range slider like <input type=\"range\"> . There are Float and Int overloads; the type of value picks one.","c":".guilib-slider .dragging .guilib-slider-track .guilib-slider-rail .guilib-slider-fill .guilib-slider-thumb .guilib-slider-field .guilib-slider-value","b":"# slider function A range slider like <input type=\"range\"> . There are Float and Int overloads; the type of value picks one. onChange fires for every new value while dragging; onChangeEnd once with the final value on release or after a key press. Save settings in onChangeEnd . Copy fun NodeBuilder.slider( value: Float / Int, onChange: ((Float) -> Unit)? = null, min: Float = 0f, max: Float = 100f, step: Float = 1f, onChangeEnd: ((Float) -> Unit)? = null, showValue: Boolean = false, format: ((Float) -> String)? = null, disabled: Boolean = false, className: String? = null, id: String? = null, style: String? = null, key: Any? = null, ) Parameter Type Default Description value Float / Int required Current value. onChange ((Float) -> Unit)? null Every new value while dragging. min Float 0f Lower bound. max Float 100f Upper bound. step Float 1f Values snap to multiples of step from min ; 0f = continuous. onChangeEnd ((Float) -> Unit)? null Final value on release / after a key press. showValue Boolean false Show the value after the slider. format ((Float) -> String)? null Formats the shown value (default: as many decimals as step ). disabled Boolean false className , id , style , key Standard props (see Elements ). Keyboard Arrows ±1 step, PageUp/PageDown ±10 %, Home/End jump to min/max The slider is 100px wide by default; set the width with style or on .guilib-slider . Example Copy var volume by useState(70f) slider(value = volume, onChange = { volume = it }, step = 5f, showValue = true, format = { \"${it.toInt()}%\" }, onChangeEnd = { config.volume = it; config.save() }) var range by useState(12) slider(value = range, onChange = { range = it }, min = 1, max = 32, showValue = true, format = { \"$it chunks\" }) CSS .guilib-slider .dragging .guilib-slider-track .guilib-slider-rail .guilib-slider-fill .guilib-slider-thumb .guilib-slider-field .guilib-slider-value"},{"t":"rangeSlider","u":"controls.html#rangeslider","k":"function","s":"A slider with two thumbs selecting a range, e.g. a filter \"kills between 5,000 and 20,000\". A press moves the nearer thumb; the thumbs can't","c":".guilib-range-slider .guilib-slider-thumb.low .guilib-slider-thumb.high + all .guilib-slider-* classes","b":"# rangeSlider function A slider with two thumbs selecting a range, e.g. a filter \"kills between 5,000 and 20,000\". A press moves the nearer thumb; the thumbs can't pass each other. Float and Int overloads. Copy fun NodeBuilder.rangeSlider( low: Float / Int, high: Float / Int, onChange: ((low, high) -> Unit)? = null, min: Float = 0f, max: Float = 100f, step: Float = 1f, onChangeEnd: ((low, high) -> Unit)? = null, showValue: Boolean = false, format: ((Float) -> String)? = null, disabled: Boolean = false, className: String? = null, id: String? = null, style: String? = null, key: Any? = null, ) Parameter Type Default Description low Float / Int required Lower end of the range. high Float / Int required Upper end. onChange ((low, high) -> Unit)? null Every change while dragging. min Float 0f max Float 100f step Float 1f onChangeEnd ((low, high) -> Unit)? null Final range on release / after a key press. showValue Boolean false Show \"low – high\". format ((Float) -> String)? null Formats each end. disabled Boolean false className , id , style , key Standard props (see Elements ). Keyboard Each thumb is focusable and moves like slider Example Copy var kills by useState(5000 to 20000) rangeSlider(low = kills.first, high = kills.second, onChange = { lo, hi -> kills = lo to hi }, min = 0, max = 50000, step = 500, showValue = true, format = { \"%,d\".format(it) }) CSS .guilib-range-slider .guilib-slider-thumb.low .guilib-slider-thumb.high + all .guilib-slider-* classes"},{"t":"numberInput","u":"controls.html#numberinput","k":"function","s":"A number field with − and + buttons that keeps the value within min..max . Values inside the range are reported while typing; anything else ","c":".guilib-number .guilib-number-input .guilib-number-dec .guilib-number-inc","b":"# numberInput function A number field with − and + buttons that keeps the value within min..max . Values inside the range are reported while typing; anything else is clamped when the field loses focus or on Enter. Typing accepts the shorthand 100k , 1.5m , 2,5k or 1b (k = thousand, m = million, b = billion, any case, . or , as decimal mark): the text stays as typed while editing and becomes the number ( 100000 ) on blur or Enter; invalid text goes back to the last value. Int and Double overloads (the Double one shows as many decimals as step ). With allowEmpty = true the value is an Int? / Double? : null shows an empty field with the placeholder, clearing the field reports null , + on an empty field starts at step (at least min ), − on an empty field does nothing, and − at min empties the field again. Copy fun NodeBuilder.numberInput( value: Int / Double, onChange: ((Int) -> Unit)? = null, allowEmpty: Boolean = –, min: Int = Int.MIN_VALUE, max: Int = Int.MAX_VALUE, step: Int = 1, wheel: Boolean = true, disabled: Boolean = false, placeholder: String? = null, stepMultiplier: (Modifiers) -> Int = Shift ×10, Ctrl ×100, Ctrl+Shift ×1000, parse: (String) -> Double? = parseNumberShorthand, className: String? = null, id: String? = null, style: String? = null, key: Any? = null, ) Parameter Type Default Description value Int / Double required Current value. onChange ((Int) -> Unit)? null New, clamped value ( Int? with allowEmpty ). allowEmpty Boolean – Only on the Int? / Double? overloads (required there): the field may be empty. min Int Int.MIN_VALUE max Int Int.MAX_VALUE step Int 1 Step of the buttons, arrows and wheel. wheel Boolean true Mouse wheel over the field steps the value. disabled Boolean false placeholder String? null stepMultiplier (Modifiers) -> Int Shift ×10, Ctrl ×100, Ctrl+Shift ×1000 Steps per click, arrow key and wheel notch for the held keys (Cmd counts as Ctrl). Replace it for other factors, e.g. { m -> if (m.shift) 64 else 1 } for stacks. parse (String) -> Double? parseNumberShorthand Turns the typed text into a number ( null = invalid). The default reads plain numbers plus k/m/b. Own formats: { t -> if (t.endsWith(\"h\")) t.dropLast(1).toDoubleOrNull()?.times(3600) else parseNumberShorthand(t) } . With a custom parser the field accepts any characters. className , id , style , key Standard props (see Elements ). Keyboard ArrowUp/ArrowDown step (Shift ×10, Ctrl ×100, Ctrl+Shift ×1000), Enter commits; holding −/+ repeats with the multiplier of the press; wheel while hovered Example Copy var slots by useState(3) numberInput(value = slots, onChange = { slots = it }, min = 1, max = 5) var price by useState(1.5) numberInput(value = price, onChange = { price = it }, min = 0.0, max = 10.0, step = 0.25) var budget by useState(2_500_000.0) // type 100k, 1.5m, 2,5k or 1b numberInput(value = budget, onChange = { budget = it }, min = 0.0, step = 100_000.0) var minCata by useState<Int?>(null) // empty = no requirement numberInput(value = minCata, onChange = { minCata = it }, allowEmpty = true, min = 0, max = 50, placeholder = \"any\") CSS .guilib-number .guilib-number-input .guilib-number-dec .guilib-number-inc"},{"t":"Choices","u":"controls.html#choices","k":"Form controls","s":"","b":""},{"t":"select","u":"controls.html#select","k":"function","s":"A dropdown. The menu opens in a portal, so it's never clipped by scroll containers. With searchable = true the menu starts with a search fie","c":"select .guilib-select-value .guilib-select-chosen .guilib-select-arrow .guilib-select-menu .guilib-select-search .guilib-select-empty .guilib-option .selected .highlighted .disabled","b":"# select function A dropdown. The menu opens in a portal, so it's never clipped by scroll containers. With searchable = true the menu starts with a search field that filters the options while typing (case-insensitive, by label or value; § codes are ignored). Copy fun NodeBuilder.select( value: String?, onChange: ((InputEvent) -> Unit)? = null, disabled: Boolean = false, placeholder: String? = null, searchable: Boolean = false, searchPlaceholder: String? = null, options: SelectBuilder.() -> Unit, className: String? = null, id: String? = null, style: String? = null, key: Any? = null, ) Parameter Type Default Description value String? required Selected option value. onChange ((InputEvent) -> Unit)? null it.value is the chosen value. disabled Boolean false placeholder String? null Shown when nothing is selected. searchable Boolean false Add a search field to the menu. searchPlaceholder String? null Placeholder of the search field (default \"Search…\"). options SelectBuilder.() -> Unit required option(value, label, disabled = false, title = null) or option(value) { +\"Label\" } . title is a tooltip for that entry, shown above the open menu. className / style go on the menu entry and on its label in the box while chosen ( .guilib-select-chosen , one span per chosen entry of a multiSelect ), e.g. to color item names by rarity; labels also take § codes. The same option works in multiSelect , radioGroup , segmented and chips . className , id , style , key Standard props (see Elements ). Keyboard ArrowUp/Down open and move, Enter/Space choose, Escape closes; typing goes to the search field Example Copy select(value = mode, onChange = { mode = it.value }) { option(\"normal\", \"Normal\") option(\"hard\", \"Hard\") option(\"expert\", \"Expert (locked)\", disabled = true) } select(value = item, onChange = { item = it.value }, placeholder = \"Search an item…\", searchable = true) { for (i in items) option(i.id, i.displayName) // labels may contain § codes } CSS select .guilib-select-value .guilib-select-chosen .guilib-select-arrow .guilib-select-menu .guilib-select-search .guilib-select-empty .guilib-option .selected .highlighted .disabled A searchable select"},{"t":"multiSelect","u":"controls.html#multiselect","k":"function","s":"A dropdown for choosing several options. Each option has a check mark, the menu stays open while toggling and the box shows the chosen label","c":"select.multiple .guilib-option-check + select classes","b":"# multiSelect function A dropdown for choosing several options. Each option has a check mark, the menu stays open while toggling and the box shows the chosen labels (each keeps its option's className / style , see select ). Copy fun NodeBuilder.multiSelect( values: List<String>, onChange: ((List<String>) -> Unit)? = null, disabled: Boolean = false, placeholder: String? = null, searchable: Boolean = false, searchPlaceholder: String? = null, options: SelectBuilder.() -> Unit, className: String? = null, id: String? = null, style: String? = null, key: Any? = null, ) Parameter Type Default Description values List<String> required Selected values. onChange ((List<String>) -> Unit)? null New selection, in option order. disabled Boolean false placeholder String? null Shown when nothing is selected. searchable Boolean false Add a search field. searchPlaceholder String? null options SelectBuilder.() -> Unit required Like select . className , id , style , key Standard props (see Elements ). Example Copy var cats by useState(listOf<String>()) multiSelect(values = cats, onChange = { cats = it }, placeholder = \"All categories\", searchable = true) { option(\"dungeons\", \"Dungeons\"); option(\"kuudra\", \"Kuudra\"); option(\"fishing\", \"Fishing\") } CSS select.multiple .guilib-option-check + select classes multiSelect with search, filtered by \"i\""},{"t":"radioGroup","u":"controls.html#radiogroup","k":"function","s":"Radio buttons (one of several). Like native radios, the selected radio is the Tab stop and the arrow keys move the selection.","c":".guilib-radio-group .vertical .guilib-radio .checked .guilib-radio-dot .guilib-radio-label","b":"# radioGroup function Radio buttons (one of several). Like native radios, the selected radio is the Tab stop and the arrow keys move the selection. Copy fun NodeBuilder.radioGroup( value: String?, onChange: ((String) -> Unit)? = null, vertical: Boolean = false, disabled: Boolean = false, options: SelectBuilder.() -> Unit, className: String? = null, id: String? = null, key: Any? = null, ) Parameter Type Default Description value String? required Selected value. onChange ((String) -> Unit)? null The chosen value. vertical Boolean false Stack the options. disabled Boolean false options SelectBuilder.() -> Unit required option(value, label, disabled) . className , id , key Standard props (see Elements ). Keyboard Arrows move the selection (skipping disabled options) Example Copy radioGroup(value = size, onChange = { size = it }) { option(\"1\", \"Solo\"); option(\"2\", \"Duo\"); option(\"3\", \"Trio\"); option(\"5\", \"Full\") } CSS .guilib-radio-group .vertical .guilib-radio .checked .guilib-radio-dot .guilib-radio-label"},{"t":"segmented","u":"controls.html#segmented","k":"function","s":"Segmented buttons: one of several, joined into a bar with a highlight that slides to the selected segment. Same API as radioGroup .","c":".guilib-segmented .guilib-segment .selected .guilib-segment-indicator","b":"# segmented function Segmented buttons: one of several, joined into a bar with a highlight that slides to the selected segment. Same API as radioGroup . Copy fun NodeBuilder.segmented( value: String?, onChange: ((String) -> Unit)? = null, vertical: Boolean = false, disabled: Boolean = false, options: SelectBuilder.() -> Unit, className: String? = null, id: String? = null, key: Any? = null, ) Parameter Type Default Description value String? required Selected value. onChange ((String) -> Unit)? null The chosen value. vertical Boolean false disabled Boolean false options SelectBuilder.() -> Unit required className , id , key Standard props (see Elements ). Example Copy segmented(value = tier, onChange = { tier = it }) { option(\"t1\", \"Basic\"); option(\"t2\", \"Hot\"); option(\"t3\", \"Burning\"); option(\"t4\", \"Fiery\"); option(\"t5\", \"Infernal\") } CSS .guilib-segmented .guilib-segment .selected .guilib-segment-indicator"},{"t":"chips","u":"controls.html#chips","k":"function","s":"Toggleable chips for picking several options, e.g. filters. A nicer alternative to multiSelect for a handful of options.","c":".guilib-chips .guilib-chip .selected .guilib-chip-check","b":"# chips function Toggleable chips for picking several options, e.g. filters. A nicer alternative to multiSelect for a handful of options. Copy fun NodeBuilder.chips( values: List<String>, onChange: ((List<String>) -> Unit)? = null, disabled: Boolean = false, options: SelectBuilder.() -> Unit, className: String? = null, key: Any? = null, ) Parameter Type Default Description values List<String> required Selected values. onChange ((List<String>) -> Unit)? null New selection, in option order. disabled Boolean false options SelectBuilder.() -> Unit required className , key Standard props (see Elements ). Example Copy chips(values = fishing, onChange = { fishing = it }) { option(\"trophy\", \"Trophy\"); option(\"lava\", \"Lava\"); option(\"water\", \"Water\") } CSS .guilib-chips .guilib-chip .selected .guilib-chip-check radioGroup, segmented, chips, multiSelect, select, rangeSlider and numberInput"},{"t":"Colors","u":"controls.html#colors","k":"Form controls","s":"","b":""},{"t":"colorPicker","u":"controls.html#colorpicker","k":"function","s":"An inline color picker: saturation/value area, hue slider, optional alpha slider, hex input and preview. Colors are ARGB Int s.","c":".guilib-color-picker .guilib-cp-sv .guilib-cp-hue .guilib-cp-alpha .guilib-cp-handle .guilib-cp-thumb .guilib-cp-preview .guilib-cp-hex","b":"# colorPicker function An inline color picker: saturation/value area, hue slider, optional alpha slider, hex input and preview. Colors are ARGB Int s. Copy fun NodeBuilder.colorPicker( value: Int, onChange: ((Int) -> Unit)? = null, alpha: Boolean = false, className: String? = null, key: Any? = null, ) Parameter Type Default Description value Int required ARGB color, e.g. 0xFF5B8DEF.toInt() . onChange ((Int) -> Unit)? null New color. alpha Boolean false Show the alpha slider and an 8-digit hex value. className , key Standard props (see Elements ). Example Copy colorPicker(value = accent, onChange = { accent = it }) CSS .guilib-color-picker .guilib-cp-sv .guilib-cp-hue .guilib-cp-alpha .guilib-cp-handle .guilib-cp-thumb .guilib-cp-preview .guilib-cp-hex colorPicker and colorInput"},{"t":"colorInput","u":"controls.html#colorinput","k":"function","s":"A swatch button showing the color and its hex code that opens a colorPicker in a popover.","c":".guilib-color-input .guilib-color-swatch .guilib-color-hex .guilib-color-popover","b":"# colorInput function A swatch button showing the color and its hex code that opens a colorPicker in a popover. Copy fun NodeBuilder.colorInput( value: Int, onChange: ((Int) -> Unit)? = null, alpha: Boolean = false, disabled: Boolean = false, className: String? = null, key: Any? = null, ) Parameter Type Default Description value Int required ARGB color. onChange ((Int) -> Unit)? null alpha Boolean false disabled Boolean false className , key Standard props (see Elements ). Example Copy colorInput(value = glow, onChange = { glow = it }, alpha = true) CSS .guilib-color-input .guilib-color-swatch .guilib-color-hex .guilib-color-popover"},{"t":"SelectBuilder","u":"controls.html#selectbuilder","k":"Form controls","s":"","b":"select , multiSelect , radioGroup , segmented and chips share the same option builder: Copy option(\"value\", \"Label\") // plain label (§ codes allowed) option(\"value\", \"Label\", disabled = true) option(\"value\") { +\"Label\" } // label from text children"},{"t":"Panels & overlays","u":"overlays.html","k":"page","s":"Navigation, expandable sections, popups and notifications: tabs, accordions, context menus, toasts, tooltips, modals, exit animations and so","b":"Navigation, expandable sections, popups and notifications: tabs, accordions, context menus, toasts, tooltips, modals, exit animations and sortable lists. Tabs with sub-tabs (pills), accordion items and a textarea"},{"t":"Navigation","u":"overlays.html#navigation","k":"Panels & overlays","s":"","b":""},{"t":"tabs","u":"overlays.html#tabs","k":"function","s":"A tab bar whose indicator slides to the active tab.","c":".guilib-tabs .underline .pills .guilib-tab-list .guilib-tab .active .guilib-tab-indicator .guilib-tab-panel","b":"# tabs function A tab bar whose indicator slides to the active tab. Tabs with a content lambda render the active tab's content below the bar. Without content lambdas only the bar is rendered and you render the content yourself from value . Copy fun NodeBuilder.tabs( value: String?, onChange: ((String) -> Unit)? = null, variant: String = \"underline\", tabs: TabsBuilder.() -> Unit, className: String? = null, id: String? = null, key: Any? = null, ) Parameter Type Default Description value String? required Active tab. onChange ((String) -> Unit)? null The clicked tab's value. variant String \"underline\" \"underline\" or \"pills\" (good for sub-categories). tabs TabsBuilder.() -> Unit required tab(value, label, disabled = false) { content } . className , id , key Standard props (see Elements ). Keyboard Left/Right (or Up/Down) switch tabs, skipping disabled ones Example Copy var category by useState(\"dungeons\") var floor by useState(\"all\") tabs(value = category, onChange = { category = it }) { tab(\"dungeons\", \"Dungeons\") { tabs(value = floor, onChange = { floor = it }, variant = \"pills\") { tab(\"all\", \"All\"); tab(\"f7\", \"F7\"); tab(\"m7\", \"M7\") } DungeonParties(floor) } tab(\"kuudra\", \"Kuudra\") { KuudraParties() } tab(\"other\", \"Other\", disabled = true) } CSS .guilib-tabs .underline .pills .guilib-tab-list .guilib-tab .active .guilib-tab-indicator .guilib-tab-panel"},{"t":"Expandable sections","u":"overlays.html#expandable-sections","k":"Panels & overlays","s":"","b":""},{"t":"details","u":"overlays.html#details","k":"function","s":"An accordion item like HTML <details> : a clickable summary row with a chevron and a body whose height animates (also when its content chang","c":".guilib-details .open .guilib-details-summary .guilib-details-chevron .guilib-details-title .guilib-details-content","b":"# details function An accordion item like HTML <details> : a clickable summary row with a chevron and a body whose height animates (also when its content changes). Uncontrolled by default. Pass open + onToggle to control it, e.g. to keep only one item open. Copy fun NodeBuilder.details( summary: String / NodeBuilder.() -> Unit, open: Boolean? = null, onToggle: ((Boolean) -> Unit)? = null, defaultOpen: Boolean = false, disabled: Boolean = false, durationMs: Long = 200, children: NodeBuilder.() -> Unit, className: String? = null, key: Any? = null, ) Parameter Type Default Description summary String / NodeBuilder.() -> Unit required Text or custom content of the summary row. open Boolean? null Controlled state; null = uncontrolled. onToggle ((Boolean) -> Unit)? null Called with the new state. defaultOpen Boolean false Initial state when uncontrolled. disabled Boolean false durationMs Long 200 Animation duration. children NodeBuilder.() -> Unit required The body. className , key Standard props (see Elements ). Keyboard Enter / Space toggle a focused summary Example Copy details(\"Requirements\") { p { +\"Catacombs 45, 10k secrets\" } } // Accordion: only one open at a time var openId by useState<String?>(null) for (party in parties) { details( summary = { b { +party.leader }; span(className = \"muted\") { +\" ${party.size}/5\" } }, open = openId == party.id, onToggle = { openId = if (it) party.id else null }, key = party.id, ) { PartyDetails(party) } } CSS .guilib-details .open .guilib-details-summary .guilib-details-chevron .guilib-details-title .guilib-details-content"},{"t":"collapse","u":"overlays.html#collapse","k":"function","s":"The building block of details : animates its height between 0 and the height of its content. While open, the height follows the content. Clo","c":".guilib-collapse .open .guilib-collapse-inner","b":"# collapse function The building block of details : animates its height between 0 and the height of its content. While open, the height follows the content. Closed content is unmounted after the animation unless keepMounted . Copy fun NodeBuilder.collapse( open: Boolean, durationMs: Long = 200, keepMounted: Boolean = false, children: NodeBuilder.() -> Unit, className: String? = null, key: Any? = null, ) Parameter Type Default Description open Boolean required durationMs Long 200 keepMounted Boolean false Keep the children (and their state) while closed. children NodeBuilder.() -> Unit required className , key Standard props (see Elements ). Example Copy button(onClick = { more = !more }) { +\"More\" } collapse(open = more) { MoreOptions() } CSS .guilib-collapse .open .guilib-collapse-inner"},{"t":"Menus","u":"overlays.html#menus","k":"Panels & overlays","s":"","b":""},{"t":"contextMenu","u":"overlays.html#contextmenu","k":"function","s":"A right-click menu for its children: opens at the mouse and is kept inside the screen (it flips up/left near the edges). The entries are bui","c":".guilib-context-anchor .guilib-menu .guilib-menu-item .highlighted .danger .disabled .guilib-menu-label .guilib-menu-shortcut .guilib-menu-header .guilib-menu-separator","b":"# contextMenu function A right-click menu for its children: opens at the mouse and is kept inside the screen (it flips up/left near the edges). The entries are built when the menu opens, so they always reflect the current state. Copy fun NodeBuilder.contextMenu( menu: MenuBuilder.() -> Unit, disabled: Boolean = false, children: NodeBuilder.() -> Unit, className: String? = null, key: Any? = null, ) Parameter Type Default Description menu MenuBuilder.() -> Unit required item(label, disabled, danger, shortcut) { onClick } , header(text) , separator() . disabled Boolean false Don't open the menu. children NodeBuilder.() -> Unit required Wrapped in a div.guilib-context-anchor (block). className , key Standard props (see Elements ). Keyboard ArrowUp/Down highlight, Enter/Space choose, Escape, Tab, a click outside, the wheel or a screen resize close Example Copy contextMenu(menu = { header(player.name) item(\"Invite\") { invite(player) } item(\"View profile\", shortcut = \"P\") { openProfile(player) } separator() item(\"Kick\", danger = true, disabled = !isLeader) { kick(player) } }) { PlayerRow(player) } CSS .guilib-context-anchor .guilib-menu .guilib-menu-item .highlighted .danger .disabled .guilib-menu-label .guilib-menu-shortcut .guilib-menu-header .guilib-menu-separator Context menu with header, highlighted item, separator and a danger item"},{"t":"Notifications","u":"overlays.html#notifications","k":"Panels & overlays","s":"","b":""},{"t":"useToast","u":"overlays.html#usetoast","k":"hook","s":"Short messages that disappear on their own (\"Party created\", \"Server not reachable\"), stacked in the bottom right corner above everything el","c":".guilib-toasts .guilib-toast .info .success .warning .error .leaving .guilib-toast-accent .guilib-toast-title .guilib-toast-message .guilib-toast-action .guilib-toast-close","b":"# useToast hook Short messages that disappear on their own (\"Party created\", \"Server not reachable\"), stacked in the bottom right corner above everything else. A click dismisses a toast; at most 5 are shown. Safe to call from any thread , e.g. from a network callback. Copy fun useToast(): Toaster class Toaster { fun show(message: String, kind: String = \"info\", title: String? = null, durationMs: Long = 3500, action: ToastAction? = null): Toast fun info(message: String, title: String? = null, durationMs: Long = 3500, action: ToastAction? = null): Toast fun success(message: String, title: String? = null, durationMs: Long = 3500, action: ToastAction? = null): Toast fun warning(message: String, title: String? = null, durationMs: Long = 3500, action: ToastAction? = null): Toast fun error(message: String, title: String? = null, durationMs: Long = 3500, action: ToastAction? = null): Toast fun clear() companion object { fun of(doc: Document): Toaster } } class Toast { fun dismiss() } class ToastAction(val label: String, val onClick: () -> Unit) durationMs <= 0 keeps the toast until it is clicked. kind becomes a CSS class, so custom kinds can be styled. action (since 0.12.2) adds a button below the message, e.g. Undo: toast.info(\"Event deleted\", action = ToastAction(\"Undo\") { restore() }) . Clicking it runs the lambda once and closes the toast; give such toasts a longer durationMs . success, warning (with title) and error toasts Example Copy val toast = useToast() button(onClick = { createParty( onSuccess = { toast.success(\"Party created\") }, onError = { toast.error(\"Server not reachable\", title = \"Party finder\") }, ) }) { +\"Create party\" } CSS .guilib-toasts .guilib-toast .info .success .warning .error .leaving .guilib-toast-accent .guilib-toast-title .guilib-toast-message .guilib-toast-action .guilib-toast-close"},{"t":"tooltip","u":"overlays.html#tooltip","k":"function","s":"A tooltip shown when hovering the children for delayMs . For simple text the title prop on any element works too. When it doesn't fit on its","c":".guilib-tooltip-anchor .guilib-tooltip","b":"# tooltip function A tooltip shown when hovering the children for delayMs . For simple text the title prop on any element works too. When it doesn't fit on its placement side it shows on the opposite side, and it is shifted to stay inside the screen (like title tips, select menus and color popovers). Copy fun NodeBuilder.tooltip( text: String, placement: String = \"top\", delayMs: Long = 300, children: NodeBuilder.() -> Unit, className: String? = null, key: Any? = null, ) fun NodeBuilder.tooltip(content: NodeBuilder.() -> Unit, placement: String = \"top\", delayMs: Long = 300, className: String? = null, key: Any? = null, children: NodeBuilder.() -> Unit) Parameter Type Default Description text String required Tooltip text (or content = { … } for rich content). placement String \"top\" top , bottom , left or right . delayMs Long 300 Hover delay. children NodeBuilder.() -> Unit required The anchor. className , key Standard props (see Elements ). Example Copy tooltip(\"Refresh the list\") { button(onClick = { refresh() }) { +\"⟳\" } } tooltip(content = { b { +\"Hyperion\" }; br(); +\"§6Legendary\" }, placement = \"right\") { item(stack) } CSS .guilib-tooltip-anchor .guilib-tooltip"},{"t":"Dialogs & animation","u":"overlays.html#dialogs-animation","k":"Panels & overlays","s":"","b":""},{"t":"modal","u":"overlays.html#modal","k":"function","s":"A dialog in a portal with a dimmed backdrop. Escape and (by default) a click on the backdrop call onClose .","c":".guilib-modal-backdrop .guilib-modal","b":"# modal function A dialog in a portal with a dimmed backdrop. Escape and (by default) a click on the backdrop call onClose . Copy fun NodeBuilder.modal( open: Boolean, onClose: (() -> Unit)? = null, closeOnBackdropClick: Boolean = true, children: NodeBuilder.() -> Unit, className: String? = null, key: Any? = null, ) Parameter Type Default Description open Boolean required onClose (() -> Unit)? null closeOnBackdropClick Boolean true children NodeBuilder.() -> Unit required Dialog content. className , key Standard props (see Elements ). Example Copy modal(open = dialog, onClose = { dialog = false }) { h3 { +\"Leave party?\" } div(className = \"row\") { button(onClick = { dialog = false }) { +\"Cancel\" } button(className = \"primary\", onClick = { leave(); dialog = false }) { +\"Leave\" } } } CSS .guilib-modal-backdrop .guilib-modal A modal dialog"},{"t":"presence","u":"overlays.html#presence","k":"function","s":"Keeps children mounted while they animate out (like Framer Motion's AnimatePresence ). When visible turns false the children render once mor","c":"","b":"# presence function Keeps children mounted while they animate out (like Framer Motion's AnimatePresence ). When visible turns false the children render once more with leaving = true and are removed after exitMs . Becoming visible again cancels the exit. Copy fun NodeBuilder.presence(visible: Boolean, exitMs: Long, key: Any? = null, children: NodeBuilder.(leaving: Boolean) -> Unit) Copy .panel { animation: slide-in 200ms ease-out; } .panel.leaving { animation: slide-out 200ms ease-in forwards; } @keyframes slide-in { from { opacity: 0; transform: translateY(-8px); } } @keyframes slide-out { to { opacity: 0; transform: translateY(-8px); } } Example Copy presence(visible = open, exitMs = 200) { leaving -> div(className = classNames(\"panel\", \"leaving\" to leaving)) { … } }"},{"t":"presenceList","u":"overlays.html#presencelist","k":"function","s":"presence for every item of a list. Items removed from items stay rendered at their old position with leaving = true for exitMs , then they a","c":"","b":"# presenceList function presence for every item of a list. Items removed from items stay rendered at their old position with leaving = true for exitMs , then they are removed. New items mount normally, so their CSS animation plays. The items are rendered straight into the parent (no wrapper element). An item that comes back during its exit is a normal item again. To let the rows below slide up, give rows a fixed height with overflow: hidden and animate height and margin to 0 in the exit keyframes. For sortableList use its exitMs parameter. Copy fun <T> NodeBuilder.presenceList(items: List<T>, key: (T) -> Any?, exitMs: Long, listKey: Any? = null, children: NodeBuilder.(item: T, leaving: Boolean) -> Unit) Parameter Type Default Description items List<T> required exitMs Long required How long a removed item stays (match your exit animation). listKey Any? null Key of the list itself. key Standard props (see Elements ). Copy .row { height: 16px; overflow: hidden; margin-bottom: 2px; animation: row-in 200ms ease-out; } .row.leaving { animation: row-out 200ms ease-in forwards; pointer-events: none; } @keyframes row-in { from { opacity: 0; height: 0; margin-bottom: 0; } } @keyframes row-out { to { opacity: 0; height: 0; margin-bottom: 0; transform: translateX(12px); } } Example Copy presenceList(parties, key = { it.id }, exitMs = 200) { party, leaving -> div(className = classNames(\"row\", \"leaving\" to leaving)) { span { +party.leader } button(onClick = { parties = parties - party }) { +\"✕\" } } }"},{"t":"Lists","u":"overlays.html#lists","k":"Panels & overlays","s":"","b":""},{"t":"sortableList","u":"overlays.html#sortablelist","k":"function","s":"A drag-to-reorder list. Items move with transform while dragging; dropping calls onReorder with the reordered list.","c":".guilib-sortable .horizontal .handle .sorting .receiving .guilib-sortable-item .dragging .away .guilib-sortable-ghost .guilib-drag-handle","b":"# sortableList function A drag-to-reorder list. Items move with transform while dragging; dropping calls onReorder with the reordered list. A drag starts after 3 px, so clicks inside items keep working, and the release after a drag clicks nothing. With handle = true only elements with the class guilib-drag-handle start a drag (use it when items contain inputs). Dragging near the edge of a scroll container scrolls it. Items are focusable; Alt + arrow keys move the focused item. Lists with the same group exchange items (kanban boards): outside its list the item follows the mouse as a ghost (in a portal; it repeats className / itemClassName , so style it through those), the list under the mouse opens a gap, and the drop calls the source's onReorder without the item and the target's with it. An item can also be dropped anywhere in the element around a list that holds no other list of the group (its kanban column, even below a short or empty list); lists placed directly next to each other without a wrapper need a min-height when empty. With exitMs > 0 removed items stay at their old position for that long with the item class .leaving (not clickable, no drag starts meanwhile), so CSS can animate them out. Items dragged into another list of the group move without an exit. Copy fun NodeBuilder.sortableList( items: List<T>, key: (T) -> Any?, onReorder: ((List<T>) -> Unit)?, horizontal: Boolean = false, handle: Boolean = false, className: String? = null, itemClassName: String? = null, listKey: Any? = null, group: String? = null, exitMs: Long = 0, children: NodeBuilder.(item: T, dragging: Boolean) -> Unit, ) Parameter Type Default Description items List<T> required onReorder ((List<T>) -> Unit)? required The reordered list; store it in state. horizontal Boolean false Sort along x (e.g. in a horizontal scroll row). handle Boolean false Only .guilib-drag-handle starts a drag. itemClassName String? null listKey Any? null Key of the list itself. group String? null Lists with the same group exchange items. exitMs Long 0 How long removed items stay with .leaving (match your exit animation). children NodeBuilder.(item: T, dragging: Boolean) -> Unit required Item content. key , className Standard props (see Elements ). Keyboard Escape cancels a drag; Alt + ↑/↓ (←/→ when horizontal), Alt + Home/End move the focused item Example Copy var tasks by useState(listOf(\"Kill Diana\", \"Dig burrows\", \"Sell loot\")) sortableList(tasks, key = { it }, onReorder = { tasks = it }) { task, dragging -> span(className = \"grip guilib-drag-handle\") { +\"⠿\" } span { +task } } // Kanban: items move between lists of the same group sortableList(todo, key = { it }, onReorder = { todo = it }, group = \"board\", className = \"column\") { task, _ -> span { +task } } sortableList(done, key = { it }, onReorder = { done = it }, group = \"board\", className = \"column\") { task, _ -> span { +task } } CSS .guilib-sortable .horizontal .handle .sorting .receiving .guilib-sortable-item .dragging .away .guilib-sortable-ghost .guilib-drag-handle Vertical lists, a list with handles, a horizontal tab strip and a kanban board mid-drag"},{"t":"Events","u":"events.html","k":"page","s":"Events work like the DOM: they bubble from the deepest element to body , and stopPropagation() / preventDefault() behave as you expect.","b":"Events work like the DOM: they bubble from the deepest element to body , and stopPropagation() / preventDefault() behave as you expect."},{"t":"Handling events","u":"events.html#handling-events","k":"Events","s":"","b":"Copy button(onClick = { e -> e.stopPropagation(); join() }) { +\"Join\" } div(onMouseEnter = { hovered = true }, onMouseLeave = { hovered = false }) { … } input(onKeyDown = { e -> if (e.key == \"Enter\") submit() }) scroll(onScroll = { e -> atBottom = e.scrollTop >= maxScroll }) e.target is the element the event happened on, e.currentTarget the one whose handler runs. mouseenter / mouseleave , focus / blur and scroll don't bubble; everything else does. Document-wide listeners: useDocumentEvent(\"keydown\") { … } (runs before element handlers)."},{"t":"Event types","u":"events.html#event-types","k":"Events","s":"","b":"Class Events Fields UIEvent all type , target , currentTarget , stopPropagation() , preventDefault() , defaultPrevented MouseEvent click dblclick contextmenu mousedown mouseup mousemove mouseenter mouseleave clientX , clientY (GUI px), offsetX , offsetY , button (0 left, 1 middle, 2 right), shiftKey , ctrlKey , altKey WheelEvent wheel deltaX , deltaY (px, positive = down) + mouse fields KeyboardEvent keydown keyup key (DOM names), keyCode (raw: GLFW key code up to 26.2, SDL scancode on 26.3 - prefer key ), modifiers , shiftKey , ctrlKey , repeat InputEvent input change value , checked FocusEvent focus blur relatedTarget ScrollEvent scroll scrollLeft , scrollTop"},{"t":"Keyboard","u":"events.html#keyboard","k":"Events","s":"","b":"key uses DOM names: \"a\" , \"Enter\" , \"Escape\" , \"ArrowUp\" , \"Tab\" , \"Backspace\" , \"Delete\" , \"Home\" , \"End\" , \"PageUp\" , \" \" …. Keyboard events go to the focused element, or to body when nothing is focused. Copy useDocumentEvent(\"keydown\") { e -> e as KeyboardEvent if (e.ctrlKey && e.key == \"f\") { searchRef.current?.focus(); e.preventDefault() } }"},{"t":"Default actions","u":"events.html#default-actions","k":"Events","s":"","b":"preventDefault() on Effect mousedown The element is not focused. wheel The scroll container doesn't scroll. keydown (Escape) The screen stays open. keydown (Enter / Space on a button) The button isn't clicked. The wheel scrolls the nearest scroll container; Shift + wheel scrolls sideways. A container that can only scroll horizontally also takes the plain wheel (unlike the web) and hands it on once it reaches its end."},{"t":"Focus","u":"events.html#focus","k":"Events","s":"","b":"Inputs, textareas, buttons, selects and elements with tabIndex are focusable. Tab / Shift+Tab move the focus. Clicking focuses the nearest focusable element; style it with :focus , :focus-visible (only keyboard focus, like browsers) or :focus-within . The first Escape blurs a focused input; the next closes the screen (unless something called preventDefault() ). Use autoFocus = true on an input to focus it when it appears, or ref.current?.focus() ."},{"t":"Element API","u":"events.html#element-api","k":"Events","s":"","b":"Via ref.current (see useElementRef ) or useDocument() : Member Description tagName , id , classList , children , parent Tree and identity. getBoundingClientRect() Border box in screen (GUI) coordinates, including transforms. querySelector(css) , querySelectorAll(css) Find descendants with any supported selector. contains(node) Whether the node is this element or inside it. focus() , blur() , isFocused Focus control. scrollTop , scrollLeft (read & write), maxScrollTop , maxScrollLeft Scroll position of scroll containers. style The computed style."},{"t":"CSS","u":"css.html","k":"page","s":"GuiLib implements the parts of CSS that UIs need, with the real cascade. This page lists every supported selector, value and property.","b":"GuiLib implements the parts of CSS that UIs need, with the real cascade. This page lists every supported selector, value and property."},{"t":"Where styles come from","u":"css.html#where-styles-come-from","k":"CSS","s":"","b":".css files from resources: GuiLib.open(App, stylesheets = listOf(\"mymod:ui/app.css\")) . Inline style strings: div(style = \"width: 20px; color: red\") . The built-in user-agent stylesheet assets/guilib/css/ua.css (lowest priority) that styles tags and controls. Cascade, specificity, !important , inheritance and inherit / initial / unset work like the web. Invalid or unsupported CSS is skipped with a warning ( file:line:col , \"did you mean …\"), never a crash."},{"t":"Selectors","u":"css.html#selectors","k":"CSS","s":"","b":"Kind Supported Simple * tag .class #id [attr] [attr=v] [attr^=v] [attr$=v] [attr*=v] , compounds like button.primary:hover Combinators descendant a b , child a > b , a + b , a ~ b , lists a, b State :hover :active :focus :focus-visible :focus-within :disabled :enabled :checked , :scrolling (GuiLib-only: while the scroll position changes and 150 ms after) Structural :first-child :last-child :only-child :root :not(…) :nth-child() :nth-last-child() :nth-of-type() :nth-last-of-type() ( odd , even , 3 , 2n+1 , -n+3 ); :nth-child(even of .x) / :nth-last-child(… of S) count only siblings matching S Pseudo-elements ::before ::after (also :before / :after ) at the end of a selector, e.g. .crumb + .crumb::before , .btn:hover::after ; ::placeholder of inputs and textareas At-rules @keyframes ; @media (nestable): comma lists, not / only , screen / all / print , and / or ; features width height aspect-ratio orientation in GUI px, resolution = Minecraft's GUI scale ( min-resolution: 3dppx or 3x ), hover (hover), pointer (fine), prefers-reduced-motion (no-preference), prefers-color-scheme (dark); min- / max- prefixes and range syntax (400px <= width < 640px) . Styles update when the window size or GUI scale changes. @supports (nestable with @media ): (property: value) is true when GuiLib knows the property and can parse the value (custom properties and var() values count), selector(…) when it can parse the selector, plus not / and / or and parentheses; decided once when the sheet loads. Use it for fallbacks: @supports not (display: contents) { … } . @font-face (see Fonts ). Not supported: other pseudo-elements ( ::selection , ::marker , …), @import , @container ."},{"t":"::before and ::after","u":"css.html#before-and-after","k":"CSS","s":"","b":"Generated boxes before and after an element's children, like the web. A rule needs content to create one: strings, attr(name) (an attribute of the element, e.g. attr(title) ), or \"\" for purely decorative boxes. content: none (or normal ) removes it. The box is inline by default, inherits from the element and can be styled like any element: display , sizes, position: absolute , backgrounds, borders, shadows, transitions and animations. Hover and clicks on the box count as the element (it is not in children and querySelector doesn't find it). Inputs, textareas, images, items and <br> don't get pseudo-elements. content has no url() , counters or quotes. Copy .crumb + .crumb::before { content: \"›\"; margin: 0 5px; color: #949ba4 } .required::after { content: \" *\"; color: #e5484d } .bell { position: relative } .bell::after { content: \"\"; position: absolute; top: -3px; right: -3px; width: 7px; height: 7px; border-radius: 4px; background-color: #e5484d } .more::after { content: \" →\"; opacity: 0; transition: opacity 150ms } .more:hover::after { opacity: 1 } .tip::after { content: attr(title) }"},{"t":"::placeholder","u":"css.html#placeholder","k":"CSS","s":"","b":"Styles the placeholder text of input , textarea and numberInput while the field is empty. Text properties ( color , font-style , font-weight , letter-spacing …) and opacity apply; the host's state works too ( :focus::placeholder ). It beats GuiLib's built-in .guilib-placeholder rule, which still works. Copy .search::placeholder { color: #e0b04a; font-style: italic } .search:focus::placeholder { color: #e0b04a66 }"},{"t":"Values","u":"css.html#values","k":"CSS","s":"","b":"Kind Supported Lengths px (GUI pixels), % , em , rem , vw , vh , vmin , vmax , unitless 0 Colors #rgb #rgba #rrggbb #rrggbbaa , rgb() / rgba() (comma or space syntax), hsl() / hsla() , all named colors, transparent , currentColor Variables --name: value with var(--name, fallback) Math calc() , min() , max() , clamp() , e.g. width: calc(100% - 2em) Angles deg rad grad turn"},{"t":"Box model & layout","u":"css.html#layout","k":"CSS","s":"","b":"Group Properties Box width height min-width min-height max-width max-height box-sizing margin(-*) padding(-*) Aspect ratio aspect-ratio ( 16 / 9 , 1.5 , auto , auto 16/9 ): a box with only a width (or only a height) gets the other side from the ratio, measured on the border box (content box with box-sizing: content-box ). Like the web, it still grows to fit its content unless overflow clips. Images keep their own ratio. Outline outline outline-width outline-style outline-color outline-offset ( auto = solid): drawn outside the border box (inside with a negative offset), on top of the content, following border-radius . Takes no space and isn't clickable – good for focus rings: button:focus-visible { outline: 1px solid var(--guilib-accent); outline-offset: 2px } . Border border border-(top|right|bottom|left) border-width border-style border-color border-*-width/-style/-color border-radius border-*-radius ; styles none hidden solid dashed dotted (dashes are 3× the border width with the gaps stretched to fit and a dash in each square corner, like Chrome; dots are round from 2px; a uniform dashed border draws its rounded corners as solid arcs, a dotted one puts dots along them; the background shows through the gaps) Display display : block inline inline-block flex inline-flex grid inline-grid table inline-table table-row-group table-header-group table-footer-group table-row table-cell table-caption table-column table-column-group none Tables border-collapse ( separate collapse : no spacing, the table's padding is ignored, shared borders are drawn once and the wider one wins), border-spacing (one or two lengths), table-layout ( auto ; fixed with a table width takes widths from col and the first row only), caption-side ( top bottom ), vertical-align on cells ( top middle bottom baseline ). See Tables . Inline vertical-align ( baseline sub super text-top text-bottom middle top bottom , a length, or a % of the line height) for inline-block / inline-flex / img / item boxes, and on display: inline elements ( span , sub , sup , …) to raise or lower their text (shifts add up when nested; the line grows to fit) Position position : static relative absolute fixed ; top right bottom left inset z-index Overflow overflow overflow-x overflow-y ( visible hidden auto scroll ), scrollbar-width ( auto thin none ), scrollbar-color: <thumb> <track> (animatable); class guilib-autohide = scrollbar that fades out when idle, colors via --guilib-scrollbar-thumb / --guilib-scrollbar-track Flexbox flex flex-direction flex-wrap flex-flow flex-grow flex-shrink flex-basis justify-content align-items align-self align-content (lines of a wrapping container with a fixed height; normal stretches them) place-items place-content gap row-gap column-gap order , auto margins Grid grid-template-columns / -rows ( px % fr auto min-content max-content minmax() repeat(n | auto-fill | auto-fit, …) ), grid-template-areas grid-area grid-row grid-column grid-*-start/-end (lines, negative lines, span n , area names), grid-auto-rows grid-auto-columns grid-auto-flow ( row column dense ), justify-items justify-self place-self ; justify-content / align-content distribute the columns / rows CSS grid: fr tracks, spans, template areas, auto-fill and auto-fit Flexbox and positioning"},{"t":"Text & visuals","u":"css.html#text-visuals","k":"CSS","s":"","b":"Group Properties Text color font-family font-size font-weight font-style line-height text-align white-space text-overflow text-decoration text-shadow letter-spacing ( normal or a length, also negative; added after every character) Text wrapping text-transform ( uppercase lowercase capitalize ; inputs show what was typed), word-break ( break-all breaks between any characters, break-word , keep-all = normal), overflow-wrap / word-wrap ( break-word : a word too long for its line is broken; anywhere : also lets the box shrink below it), line-clamp / -webkit-line-clamp: N (the first N lines, the last one ends with \"…\"; use with overflow: hidden , the display: -webkit-box; -webkit-box-orient: vertical recipe works as well). Background background background-color background-image background-size background-position background-repeat background-origin background-clip : comma list of layers (first on top): url(\"modid:path.png\") , linear-gradient(…) (angles, to right , stops with positions, hard stops), radial-gradient(…) ( circle / ellipse , size keywords, at <position> ), conic-gradient(…) ( from <angle> , at <position> , stops in angles or %; from is animatable) and the repeating-linear/radial/conic-gradient(…) forms. Gradients respect border-radius . Background layout Per layer (comma lists, cycled): background-size ( auto cover contain , one or two lengths/%; auto keeps the ratio), background-position ( center , right top , 25% 75% , right 10px bottom 5px ), background-repeat ( repeat no-repeat repeat-x repeat-y space round , or two values), background-origin ( padding-box default, border-box , content-box ), background-clip ( border-box default, padding-box , content-box ; the color follows the bottom layer). Shorthand: background: #111 url(\"mymod:bg.png\") center / cover no-repeat . GuiLib default: a layer without size, position and repeat is stretched over the box (browsers draw it at natural size and tile it); set any of them for web behavior. See Differences . Shadow box-shadow : none or a comma list of [inset] <x> <y> [<blur> [<spread>]] [<color>] (first on top, color defaults to currentColor ). Real Gaussian blur that follows border-radius ; outer shadows are never drawn under the box, so translucent backgrounds stay clean. Animatable. Filter filter : brightness() contrast() grayscale() sepia() saturate() hue-rotate() invert() opacity() blur() drop-shadow(<x> <y> [<blur>] [<color>]) , applied to the element and everything inside it (positioned descendants too). Color functions are exact for boxes, text, gradients and images. blur() works on boxes, borders, shadows and images; text and gradients stay sharp. drop-shadow() follows rounded boxes, image alpha and text (unblurred for text). Items, entities, player heads and animated GIFs aren't filtered. Animatable, e.g. .card { filter: grayscale(1); transition: filter 300ms } .card:hover { filter: none } . Visual opacity visibility object-fit Interaction cursor ( auto default pointer text not-allowed crosshair move ns-resize ew-resize row-resize col-resize grab grabbing none ; none hides the system cursor (draw your own at the mouse with onMouseMove ); a drag cursor stays while the left button is held), pointer-events , user-select (parsed only), caret-color ( auto = text color, or a color; inherited, animatable) for inputs and textareas, accent-color ( auto or a color; inherited) for the checked/filled parts of checkboxes, radios, switches, sliders, segmented/tab indicators and selected chips – not focus borders or menus (use --guilib-accent for a whole theme) Generated content content (strings, attr(name) , none / normal ), only on ::before / ::after Rounded corners, borders (solid, dashed, dotted), gradients, shadows and opacity, drawn by GuiLib's own anti-aliased shader filter on images and cards: color functions, blur() and drop-shadow()"},{"t":"Animation","u":"css.html#animation","k":"CSS","s":"","b":"transition (+ -property -duration -timing-function -delay ) and animation (+ -name -duration -timing-function -delay -iteration-count -direction -fill-mode -play-state ) with @keyframes . Easing: linear ease ease-in ease-out ease-in-out cubic-bezier() steps() . Animatable: colors, lengths (also px ↔ % via calc), numbers ( opacity , flex-grow , font-size …), radii, line-height , text-shadow , letter-spacing , box-shadow , filter , scrollbar colors, gradient stop colors, visibility , transform , transform-origin . Other values switch at 50 % in keyframes and don't transition. Copy .card { transition: background-color 150ms, transform 150ms ease-out; } .card:hover { background-color: #333; transform: scale(1.05); } @keyframes spin { to { transform: rotate(360deg); } } .spinner { animation: spin 1s linear infinite; } @keyframes slide-in { from { opacity: 0; transform: translateX(-20px); } } .item { animation: slide-in 300ms ease-out backwards; } /* + style = \"animation-delay: ${i * 50}ms\" */ Transitions, keyframes and 2D transforms"},{"t":"Transforms","u":"css.html#transforms","k":"CSS","s":"","b":"transform with translate() translateX() translateY() scale() scaleX() scaleY() rotate() skew() skewX() skewY() matrix(a, b, c, d, tx, ty) and none ; transform-origin (lengths, %, keywords; default 50% 50% ). Like CSS, transforms don't affect layout. Clicks and getBoundingClientRect() follow the transformed box; hit-testing uses the exact rotated shape. Translate/scale stay pixel-exact, and scaled text is re-rendered at its new size, so it stays sharp. Rotated or skewed content is drawn through a matrix. Transforms interpolate when both lists have the same functions in the same order ( none matches anything)."},{"t":"Theming built-in controls","u":"css.html#theming","k":"CSS","s":"","b":"Every built-in control is made of plain elements with guilib-* classes and is styled by ua.css , which has the lowest priority. Every color in ua.css comes from a --guilib-* variable , so a theme only overrides variables on :root and never has to repeat the control rules: Copy /* A light theme for every built-in control */ :root { --guilib-text: #1f2328; --guilib-text-muted: #59636e; --guilib-accent: #0969da; --guilib-surface: #f6f8fa; /* select menu, modal, color picker */ --guilib-surface-2: #ffffff; /* inputs, select, chips */ --guilib-surface-3: #ffffff; /* tooltips, toasts, menus */ --guilib-border: #d1d9e0; --guilib-button: #f0f2f4; --guilib-button-hover: #e4e8eb; } /* Only the checked / filled parts of the controls in one panel (like browsers) */ .loot-filters { accent-color: #e0b04a; } /* Or restyle a single control */ .guilib-switch.checked .guilib-switch-track { background-color: #3ba55d; border-color: #3ba55d; } .guilib-slider { width: 160px; } The same controls with the default, a light and an emerald set of variables (Showcase → Colors) Variable Default Used for --guilib-text #f2f3f5 default text, buttons, inputs --guilib-text-strong #ffffff selected tabs, segments, chips --guilib-text-secondary #dbdee1 toast messages --guilib-text-muted #b5bac1 inactive tabs / segments / chips, slider value, select arrow --guilib-text-subtle #80848e placeholders, menu shortcuts and headers, empty hints --guilib-link #6cb6ff a --guilib-accent #5b8def sliders, switches, tabs, focus borders, selected states --guilib-accent-soft rgba(91, 141, 239, 0.25) selected chip background --guilib-on-accent #ffffff text and check marks on an accent background --guilib-on-accent-muted #e3e5e8 menu shortcut of the highlighted item --guilib-selection rgba(91, 141, 239, 0.45) text selection in inputs --guilib-surface #2b2d31 select menu, modal, color picker, number input buttons --guilib-surface-2 #1e1f22 inputs, select, radio, segmented, chips --guilib-surface-3 #111214 tooltips, toasts, menus --guilib-highlight #3f4248 highlighted select option --guilib-tint / --guilib-tint-strong rgba(255, 255, 255, 0.06) / 0.08 hover and focus tint on tabs, segments, details --guilib-shade rgba(0, 0, 0, 0.15) details background --guilib-backdrop rgba(0, 0, 0, 0.55) modal backdrop --guilib-border #4e5058 inputs, select, menus, modal, chips, radio --guilib-border-hover #6d6f78 hovered input, select, number input --guilib-border-strong #80848e hovered switch, radio, chip --guilib-border-subtle #3f4147 tooltips, toasts, menus, tab underline, details, separators --guilib-divider rgba(255, 255, 255, 0.15) hr --guilib-focus #ffffff focus border of switch, radio, chip, slider --guilib-button / -hover / -active / -border #3c3f45 / #4a4e55 / #2f3236 / #55595f button --guilib-track / --guilib-track-border #4e5058 / #5d6068 switch and slider track --guilib-thumb #ffffff switch / slider thumb, checked radio dot --guilib-success / --guilib-warning / --guilib-danger #3ba55d / #faa61a / #ed4245 toast kinds, danger menu item (highlighted) --guilib-danger-text #f47b7d danger menu item --guilib-scrollbar-thumb / -track #ffffff80 / #00000020 scrollbars (also .guilib-autohide ) --guilib-picker-handle / --guilib-swatch-border #ffffff / #ffffff55 color picker handles, color input swatch Variables can also be set on any element to restyle just that subtree. Set color: var(--guilib-text) there too, because the inherited text color was already resolved on body . Menus, tooltips, select dropdowns, modals and toasts are rendered in an overlay under body , so they follow the variables on :root (or a useBodyClass theme class), not the subtree they were opened from. The CSS classes of each control are listed on Form controls and Panels & overlays ."}];
